window.CODE_INDEX = {"classes":{"ComposePost":{"appearsIn":[["composer","h-classes","Logic \u00b7 class diagram"],["composer","h-widgets","Screen \u00b7 component composition"],["composer","h-sequence","Write and publish a thread \u00b7 sequence"],["index","h-screens","Screens \u00b7 how the user moves"]],"code":"export const ComposePost = ({\n  replyTo,\n  onPost,\n  onPostSuccess,\n  quote: initQuote,\n  quoteUri: initQuoteUri,\n  mention: initMention,\n  text: initText,\n  imageUris: initImageUris,\n  videoUri: initVideoUri,\n  openGallery,\n  logContext,\n  cancelRef,\n}: Props & {\n  cancelRef?: React.RefObject<CancelRef | null>\n}) => {\n  const {currentAccount} = useSession()\n  const t = useTheme()\n  const ax = useAnalytics()\n  const client = useAppviewClient()\n  const chatClient = useChatClient()\n  const pdsClient = usePdsClient()\n  const queryClient = useQueryClient()\n  /*\n   * The host the video service-auth token is minted for. This is the same value\n   * that seeds the session's PDS routing, so the audience always matches the host\n   * the upload actually reaches; a mismatch would 401 the upload.\n   */\n  const currentDispatchUrl = currentAccount!.pdsUrl ?? currentAccount!.service\n  const {closeComposer} = useComposerControls()\n  const {t: l, i18n} = useLingui()\n  const requireAltTextEnabled = useRequireAltTextEnabled()\n  const langPrefs = useLanguagePrefs()\n  const setLangPrefs = useLanguagePrefsApi()\n  const textInputRef = useRef<TextInputRef>(null)\n  const discardPromptControl = Prompt.usePromptControl()\n  const emptyPostsPromptControl = Prompt.usePromptControl()\n  const skipEmptyConfirmedRef = useRef(false)\n  const {mutateAsync: saveDraft, isPending: isSavingDraft} =\n    useSaveDraftMutation()\n  const {mutate: cleanupPublishedDraft} = useCleanupPublishedDraftMutation()\n  const {closeAllDialogs} = useDialogStateControlContext()\n  const {data: preferences} = usePreferencesQuery()\n  const navigation = useNavigation<NavigationProp>()\n\n  const [isPublishing, setIsPublishing] = useState(false)\n  const [publishingStage, setPublishingStage] = useState('')\n  const [error, setError] = useState('')\n\n  /**\n   * Track when a draft was created so we can measure draft age in metrics.\n   * Set when a draft is loaded via handleSelectDraft.\n   */\n  const [loadedDraftCreatedAt, setLoadedDraftCreatedAt] = useState<\n    string | null\n  >(null)\n\n  /**\n   * A manual selection or accepted suggestion applies only to this composer\n   * session, without changing the primary language preference.\n   */\n  const [selectedPostLanguage, setSelectedPostLanguage] = useState<\n    string | null\n  >(null)\n\n  /**\n   * The language(s) of the post being replied to.\n   */\n  const [replyToLanguages, setReplyToLanguages] = useState<string[]>(\n    replyTo?.langs || [],\n  )\n\n  /**\n   * Default to the primary language, ignoring the legacy sticky post language\n   * preference. Manual selections and accepted suggestions apply locally.\n   */\n  const currentLanguages = useMemo(\n    () =>\n      selectedPostLanguage\n        ? toPostLanguages(selectedPostLanguage)\n        : [langPrefs.primaryLanguage],\n    [selectedPostLanguage, langPrefs.primaryLanguage],\n  )\n\n  /**\n   * When the user selects a language from the composer language selector,\n   * override the current selection and clear reply language suggestions.\n   */\n  const onSelectLanguage = (language: string) => {\n    setSelectedPostLanguage(language)\n    setReplyToLanguages([])\n  }\n\n  /**\n   * Timestamp (ms) of the last honored nudge from language detection.\n   * Used to rate-limit the pulse animation: we ignore back-to-back\n   * nudges that arrive within NUDGE_COOLDOWN_MS. Consumers key an effect\n   * on this value \u2014 it only changes when we actually want to re-pulse.\n   */\n  const [languageNudgeAt, setLanguageNudgeAt] = useState(0)\n  const onLanguageNudge = () => {\n    const now = Date.now()\n    // ignore back-to-back nudges within 10s; only update state (and\n    // therefore re-pulse) once the cooldown has elapsed\n    setLanguageNudgeAt(prev => (now - prev > 10_000 ? now : prev))\n  }\n\n  const [composerState, composerDispatch] = useReducer(\n    composerReducer,\n    {\n      initImageUris,\n      initQuoteUri: initQuote?.uri ?? initQuoteUri,\n      initText,\n      initMention,\n      initInteractionSettings: preferences?.postInteractionSettings,\n    },\n    createComposerState,\n  )\n\n  const thread = composerState.thread\n\n  /*\n   * A quote opened by URI (from a deep link) skips the quote button's checks,\n   * so run them once the post resolves. When it can't be quoted, drop the\n   * quote and keep whatever else came with it.\n   */\n  const [uncheckedQuoteUri] = useState(() =>\n    initQuoteUri && !initQuote ? thread.posts[0].embed.quote?.uri : undefined,\n  )\n  const {data: uncheckedQuote, error: uncheckedQuoteError} = useQuery({\n    ...resolveLinkQueryOptions(\n      {appviewClient: client, chatClient},\n      uncheckedQuoteUri ?? '',\n    ),\n    enabled: !!uncheckedQuoteUri,\n  })\n  useEffect(() => {\n    if (!uncheckedQuoteUri) return\n    let problem: {message: string; type: 'error' | 'warning'} | undefined\n    if (uncheckedQuoteError) {\n      problem =\n        uncheckedQuoteError instanceof EmbeddingDisabledError\n          ? {\n              message: l`This post's author has disabled quote posts.`,\n              type: 'warning',\n            }\n          : {message: l`Couldn\u2019t load the post to quote`, type: 'error'}\n    } else if (\n      uncheckedQuote?.type === 'record' &&\n      uncheckedQuote.kind === 'post'\n    ) {\n      const author = uncheckedQuote.view.author.viewer\n      if (author?.blocking || author?.blockedBy || author?.blockingByList) {\n        problem = {\n          message: l`Cannot interact with a blocked user`,\n          type: 'warning',\n        }\n      }\n    }\n    if (!problem) return\n    const post = thread.posts.find(\n      p => p.embed.quote?.uri === uncheckedQuoteUri,\n    )\n    if (!post) return\n    composerDispatch({\n      type: 'update_post',\n      postId: post.id,\n      postAction: {type: 'embed_remove_quote'},\n    })\n    Toast.show(problem.message, {type: problem.type})\n  }, [uncheckedQuoteUri, uncheckedQuote, uncheckedQuoteError, thread, l])\n\n  // Clear error when composer content changes, but only if all posts are\n  // back within the character limit.\n  const allPostsWithinLimit = thread.posts.every(\n    post => post.richtext.graphemeLength <= MAX_DRAFT_GRAPHEME_LENGTH,\n  )\n\n  const activePost = thread.posts[composerState.activePostIndex]\n  const nextPost: PostDraft | undefined =\n    thread.posts[composerState.activePostIndex + 1]\n  const dispatch = useCallback(\n    (postAction: PostAction) => {\n      composerDispatch({\n        type: 'update_post',\n        postId: activePost.id,\n        postAction,\n      })\n    },\n    [activePost.id],\n  )\n\n  const selectVideo = useCallback(\n    async (postId: string, asset: ImagePickerAsset) => {\n      /*\n       * Share-extension deeplinks deliver a video URI without duration, so\n       * probe before we decide whether to compress. The picker and web paste\n       * paths already populate duration upstream. GIFs must skip the probe:\n       * they have no video track, so the iOS prober never resolves or rejects\n       * and the await below would hang forever.\n       */\n      if (\n        asset.duration == null &&\n        IS_NATIVE &&\n        asset.mimeType !== 'image/gif'\n      ) {\n        try {\n          const probed = await getVideoMetadata(asset.uri, asset.mimeType)\n          asset = {\n            ...asset,\n            mimeType: probed.mimeType ?? asset.mimeType,\n            width: probed.width ?? asset.width,\n            height: probed.height ?? asset.height,\n            duration: probed.duration,\n          }\n        } catch (e) {\n          logger.warn('selectVideo: duration probe failed', {safeMessage: e})\n        }\n      }\n\n      const abortController = new AbortController()\n      const telemetry = createVideoTelemetry({\n        asset,\n        signal: abortController.signal,\n        metric: ax.metric,\n      })\n      telemetry.picked()\n      composerDispatch({\n        type: 'update_post',\n        postId: postId,\n        postAction: {\n          type: 'embed_add_video',\n          asset,\n          abortController,\n          telemetry,\n        },\n      })\n\n      /*\n       * Fail early on duration so we don't spend time compressing a video the\n       * server would reject anyway.\n       */\n      if (asset.duration != null && asset.duration > VIDEO_MAX_DURATION_MS) {\n        composerDispatch({\n          type: 'update_post',\n          postId: postId,\n          postAction: {\n            type: 'embed_update_video',\n            videoAction: {\n              type: 'to_error',\n              error: l`Videos must be 10 minutes or less.`,\n              signal: abortController.signal,\n            },\n          },\n        })\n        return\n      }\n\n      void processVideo(\n        asset,\n        videoAction => {\n          composerDispatch({\n            type: 'update_post',\n            postId: postId,\n            postAction: {\n              type: 'embed_update_video',\n              videoAction,\n            },\n          })\n        },\n        pdsClient,\n        currentDispatchUrl,\n        abortController.signal,\n        i18n,\n        telemetry,\n      )\n    },\n    [l, i18n, pdsClient, currentDispatchUrl, composerDispatch, ax.metric],\n  )\n\n  const onInitVideo = useNonReactiveCallback(() => {\n    if (initVideoUri) {\n      void selectVideo(activePost.id, initVideoUri)\n    }\n  })\n\n  useEffect(() => {\n    onInitVideo()\n  }, [onInitVideo])\n\n  // Fire composer:open metric on mount\n  useCallOnce(() => {\n    ax.metric('composer:open', {\n      logContext: logContext ?? 'Other',\n      isReply: !!replyTo,\n      hasQuote: !!initQuote || !!initQuoteUri,\n      hasDraft: false,\n    })\n  })()\n\n  const clearVideo = useCallback(\n    (postId: string) => {\n      composerDispatch({\n        type: 'update_post',\n        postId: postId,\n        postAction: {\n          type: 'embed_remove_video',\n        },\n      })\n    },\n    [composerDispatch],\n  )\n\n  const restoreVideo = useCallback(\n    async (postId: string, videoInfo: RestoredVideo) => {\n      try {\n        logger.debug('restoring video from draft', {\n          postId,\n          videoUri: videoInfo.uri,\n          altText: videoInfo.altText,\n          captionCount: videoInfo.captions.length,\n        })\n\n        let asset: ImagePickerAsset\n\n        if (IS_WEB) {\n          // Web: Convert blob URL to a File, then get video metadata (returns data URL)\n          const response = await fetch(videoInfo.uri)\n          const blob = await response.blob()\n          const file = new File([blob], 'restored-video', {\n            type: videoInfo.mimeType,\n          })\n          asset = await getVideoMetadata(file)\n        } else {\n          let uri = videoInfo.uri\n          if (IS_ANDROID) {\n            // Android: expo-file-system double-encodes filenames with special chars.\n            // The native metadata probe can't handle the double-encoded URI, so\n            // copy it to a temp file with a simple name.\n            const sourceFile = new FileSystem.File(videoInfo.uri)\n            const tempFileName = `draft-video-${Date.now()}.${mimeToExt(videoInfo.mimeType)}`\n            const tempFile = new FileSystem.File(\n              FileSystem.Paths.cache,\n              tempFileName,\n            )\n            await sourceFile.copy(tempFile)\n            logger.debug('restoreVideo: copied to temp file', {\n              source: videoInfo.uri,\n              temp: tempFile.uri,\n            })\n            uri = tempFile.uri\n          }\n          asset = await getVideoMetadata(uri, videoInfo.mimeType)\n        }\n\n        // Start video processing using existing flow\n        const abortController = new AbortController()\n        const telemetry = createVideoTelemetry({\n          asset,\n          signal: abortController.signal,\n          metric: ax.metric,\n        })\n        telemetry.picked()\n        composerDispatch({\n          type: 'update_post',\n          postId,\n          postAction: {\n            type: 'embed_add_video',\n            asset,\n            abortController,\n            telemetry,\n          },\n        })\n\n        if (asset.duration != null && asset.duration > VIDEO_MAX_DURATION_MS) {\n          composerDispatch({\n            type: 'update_post',\n            postId,\n            postAction: {\n              type: 'embed_update_video',\n              videoAction: {\n                type: 'to_error',\n                error: l`Videos must be 10 minutes or less.`,\n                signal: abortController.signal,\n              },\n            },\n          })\n          return\n        }\n\n        // Restore alt text immediately\n        if (videoInfo.altText) {\n          composerDispatch({\n            type: 'update_post',\n            postId,\n            postAction: {\n              type: 'embed_update_video',\n              videoAction: {\n                type: 'update_alt_text',\n                altText: videoInfo.altText,\n                signal: abortController.signal,\n              },\n            },\n          })\n        }\n\n        // Restore captions (web only - captions use File objects)\n        if (IS_WEB && videoInfo.captions.length > 0) {\n          const captionTracks = videoInfo.captions.map(c => ({\n            lang: c.lang,\n            file: new File([c.content], `caption-${c.lang}.vtt`, {\n              type: 'text/vtt',\n            }),\n          }))\n          composerDispatch({\n            type: 'update_post',\n            postId,\n            postAction: {\n              type: 'embed_update_video',\n              videoAction: {\n                type: 'update_captions',\n                updater: () => captionTracks,\n                signal: abortController.signal,\n              },\n            },\n          })\n        }\n\n        // Start video compression and upload\n        void processVideo(\n          asset,\n          videoAction => {\n            composerDispatch({\n              type: 'update_post',\n              postId,\n              postAction: {\n                type: 'embed_update_video',\n                videoAction,\n              },\n            })\n          },\n          pdsClient,\n          currentDispatchUrl,\n          abortController.signal,\n          i18n,\n          telemetry,\n        )\n      } catch (e) {\n        logger.error('Failed to restore video from draft', {\n          postId,\n          error: e,\n        })\n      }\n    },\n    [l, i18n, pdsClient, currentDispatchUrl, composerDispatch, ax.metric],\n  )\n\n  const handleSelectDraft = useCallback(\n    async (draftSummary: DraftSummary) => {\n      logger.debug('loading draft for editing', {\n        draftId: draftSummary.id,\n      })\n\n      // Load local media files for the draft\n      const {loadedMedia} = await loadDraftMedia(draftSummary.draft)\n\n      // Extract original localRefs for orphan detection on save\n      const originalLocalRefs = extractLocalRefs(draftSummary.draft)\n\n      logger.debug('draft loaded', {\n        draftId: draftSummary.id,\n        loadedMediaCount: loadedMedia.size,\n        originalLocalRefCount: originalLocalRefs.size,\n      })\n\n      // Convert server draft to composer posts (videos returned separately)\n      const {posts, restoredVideos} = await draftToComposerPosts(\n        draftSummary.draft,\n        loadedMedia,\n      )\n\n      // Dispatch restore action (this also sets draftId in state)\n      composerDispatch({\n        type: 'restore_from_draft',\n        draftId: draftSummary.id,\n        posts,\n        threadgateAllow: draftSummary.draft.threadgateAllow,\n        postgateEmbeddingRules: draftSummary.draft.postgateEmbeddingRules,\n        loadedMedia,\n        originalLocalRefs,\n      })\n\n      // Track when the draft was created for metrics\n      setLoadedDraftCreatedAt(draftSummary.createdAt)\n\n      // Fire draft:load metric\n      const draftPosts = draftSummary.posts\n      const draftAgeMs = Date.now() - new Date(draftSummary.createdAt).getTime()\n      ax.metric('draft:load', {\n        draftAgeMs,\n        hasText: draftPosts.some(p => p.text.trim().length > 0),\n        hasImages: draftPosts.some(p => p.images && p.images.length > 0),\n        hasVideo: draftPosts.some(p => !!p.video),\n        hasGif: draftPosts.some(p => !!p.gif),\n        postCount: draftPosts.length,\n      })\n\n      // Initiate video processing for any restored videos\n      // This is async but we don't await - videos process in the background\n      for (const [postIndex, videoInfo] of restoredVideos) {\n        const postId = posts[postIndex].id\n        void restoreVideo(postId, videoInfo)\n      }\n    },\n    [composerDispatch, restoreVideo, ax],\n  )\n\n  const [publishOnUpload, setPublishOnUpload] = useState(false)\n\n  const onClose = useCallback(() => {\n    // HACKFIX: Android keyboard doesn't consistently dismiss IME\n    // TODO: investigate the root cause and fix properly -sfn\n    if (IS_ANDROID) {\n      Keyboard.dismiss()\n    }\n    closeComposer()\n    clearThumbnailCache(queryClient)\n    revokeAllMediaUrls()\n  }, [closeComposer, queryClient])\n\n  const getDraftSaveError = useCallback(\n    (e: unknown): string => {\n      if (\n        matchXrpcError(e, app.bsky.draft.createDraft) === 'DraftLimitReached'\n      ) {\n        return l`You've reached the maximum number of drafts`\n      }\n      return l`Failed to save draft`\n    },\n    [l],\n  )\n\n  const validateDraftTextOrError = useCallback((): boolean => {\n    const tooLong = composerState.thread.posts.some(\n      post => post.richtext.graphemeLength > MAX_DRAFT_GRAPHEME_LENGTH,\n    )\n    if (tooLong) {\n      setError(\n        l`One or more posts are too long to save as a draft. ${plural(MAX_DRAFT_GRAPHEME_LENGTH, {one: 'The maximum number of characters is # character.', other: 'The maximum number of characters is # characters.'})}`,\n      )\n      return false\n    }\n    return true\n  }, [composerState.thread.posts, l])\n\n  const handleSaveDraft = useCallback(async () => {\n    setError('')\n    if (!validateDraftTextOrError()) {\n      return\n    }\n    const isNewDraft = !composerState.draftId\n    try {\n      const result = await saveDraft({\n        composerState,\n        existingDraftId: composerState.draftId,\n      })\n      composerDispatch({type: 'mark_saved', draftId: result.draftId})\n\n      // Fire draft:save metric\n      const posts = composerState.thread.posts\n      ax.metric('draft:save', {\n        isNewDraft,\n        hasText: posts.some(p => p.richtext.text.trim().length > 0),\n        hasImages: posts.some(\n          p =>\n            p.embed.media?.type === 'images' ||\n            p.embed.media?.type === 'gallery',\n        ),\n        hasVideo: posts.some(p => p.embed.media?.type === 'video'),\n        hasGif: posts.some(p => p.embed.media?.type === 'gif'),\n        hasQuote: posts.some(p => !!p.embed.quote),\n        hasLink: posts.some(p => !!p.embed.link),\n        postCount: posts.length,\n        textLength: posts[0].richtext.text.length,\n      })\n\n      onClose()\n    } catch (e) {\n      logger.error('Failed to save draft', {error: e})\n      setError(getDraftSaveError(e))\n    }\n  }, [\n    saveDraft,\n    composerState,\n    composerDispatch,\n    onClose,\n    ax,\n    validateDraftTextOrError,\n    getDraftSaveError,\n  ])\n\n  // Save without closing - for use by DraftsButton\n  const saveCurrentDraft = useCallback(async (): Promise<{\n    success: boolean\n  }> => {\n    setError('')\n    if (!validateDraftTextOrError()) {\n      return {success: false}\n    }\n    try {\n      const result = await saveDraft({\n        composerState,\n        existingDraftId: composerState.draftId,\n      })\n      composerDispatch({type: 'mark_saved', draftId: result.draftId})\n      return {success: true}\n    } catch (e) {\n      setError(getDraftSaveError(e))\n      return {success: false}\n    }\n  }, [\n    saveDraft,\n    composerState,\n    composerDispatch,\n    validateDraftTextOrError,\n    getDraftSaveError,\n  ])\n\n  // Handle discard action - fires metric and closes composer\n  const handleDiscard = useCallback(() => {\n    const posts = thread.posts\n    const hasContent = posts.some(\n      post =>\n        post.richtext.text.trim().length > 0 ||\n        post.embed.media ||\n        post.embed.link,\n    )\n    ax.metric('draft:discard', {\n      logContext: 'ComposerClose',\n      hadContent: hasContent,\n      textLength: posts[0].richtext.text.length,\n    })\n    onClose()\n  }, [thread.posts, ax, onClose])\n\n  // Check if composer is empty (no content to save)\n  const isComposerEmpty = useMemo(() => {\n    // Has multiple posts means it's not empty\n    if (thread.posts.length > 1) return false\n\n    const firstPost = thread.posts[0]\n    // Has text\n    if (firstPost.richtext.text.trim().length > 0) return false\n    // Has media\n    if (firstPost.embed.media) return false\n    // Has quote\n    if (firstPost.embed.quote) return false\n    // Has link\n    if (firstPost.embed.link) return false\n\n    return true\n  }, [thread.posts])\n\n  // Clear the composer (discard current content)\n  const handleClearComposer = useCallback(() => {\n    composerDispatch({\n      type: 'clear',\n      initInteractionSettings: preferences?.postInteractionSettings,\n    })\n  }, [composerDispatch, preferences?.postInteractionSettings])\n\n  const insets = useSafeAreaInsets()\n  const viewStyles = useMemo(\n    () => ({\n      paddingTop: IS_ANDROID || IS_IPAD ? insets.top : 0,\n      paddingBottom: insets.bottom,\n    }),\n    [insets.top, insets.bottom],\n  )\n\n  const onPressCancel = useCallback(() => {\n    if (isSavingDraft) {\n      return\n    }\n    if (textInputRef.current?.maybeClosePopup()) {\n      return\n    }\n\n    const hasContent = thread.posts.some(\n      post =>\n        post.shortenedGraphemeLength > 0 || post.embed.media || post.embed.link,\n    )\n\n    // Show discard prompt if there's content AND either:\n    // - No draft is loaded (new composition)\n    // - Draft is loaded but has been modified\n    if (hasContent && (!composerState.draftId || composerState.isDirty)) {\n      closeAllDialogs()\n      Keyboard.dismiss()\n      discardPromptControl.open()\n    } else {\n      onClose()\n    }\n  }, [\n    isSavingDraft,\n    thread,\n    composerState.draftId,\n    composerState.isDirty,\n    closeAllDialogs,\n    discardPromptControl,\n    onClose,\n  ])\n\n  useImperativeHandle(cancelRef, () => ({onPressCancel}))\n\n  // On Android, pressing Back should ask confirmation.\n  useEffect(() => {\n    if (!IS_ANDROID) {\n      return\n    }\n    const backHandler = BackHandler.addEventListener(\n      'hardwareBackPress',\n      () => {\n        if (closeAllDialogs()) {\n          return true\n        }\n        onPressCancel()\n        return true\n      },\n    )\n    return () => {\n      backHandler.remove()\n    }\n  }, [onPressCancel, closeAllDialogs])\n\n  const missingAltError = useMemo(() => {\n    if (!requireAltTextEnabled) {\n      return\n    }\n    for (let i = 0; i < thread.posts.length; i++) {\n      const media = thread.posts[i].embed.media\n      if (media) {\n        if (\n          (media.type === 'images' || media.type === 'gallery') &&\n          media.images.some(img => !img.alt)\n        ) {\n          return l`One or more images is missing alt text.`\n        }\n        if (media.type === 'gif' && !media.alt) {\n          return l`One or more GIFs is missing alt text.`\n        }\n        if (\n          media.type === 'video' &&\n          media.video.status !== 'error' &&\n          !media.video.altText\n        ) {\n          return l`One or more videos is missing alt text.`\n        }\n      }\n    }\n  }, [thread, requireAltTextEnabled, l])\n\n  // Subscribe to the resolve-link cache for any link URIs in the thread so we\n  // can detect chat invites that resolved to no preview (revoked/expired) and\n  // block publishing - otherwise the post would go out without the embed.\n  const linkUris = thread.posts\n    .filter(post => post.embed.link)\n    .map(post => post.embed.link!.uri)\n  const linkQueries = useQueries({\n    queries: linkUris.map(uri => ({\n      ...resolveLinkQueryOptions({appviewClient: client, chatClient}, uri),\n      enabled: false,\n    })),\n  })\n  const hasUnavailableChatInvite = linkQueries.some(\n    q =>\n      q.data?.type === 'chat-invite' &&\n      !bsky.isType(chat.bsky.group.defs.joinLinkPreviewView, q.data.view),\n  )\n\n  const canPost =\n    !missingAltError &&\n    !hasUnavailableChatInvite &&\n    thread.posts.some(post => !isEmptyPost(post)) &&\n    thread.posts.every(\n      post =>\n        isEmptyPost(post) ||\n        (post.shortenedGraphemeLength <= MAX_GRAPHEME_LENGTH &&\n          !(\n            post.embed.media?.type === 'video' &&\n            post.embed.media.video.status === 'error'\n          )),\n    )\n\n  const getFilteredThread = useCallback((): {\n    type: 'none' | 'trailing-only' | 'non-trailing'\n    filteredThread: ThreadDraft\n  } => {\n    const nonEmptyPosts = thread.posts.filter(post => !isEmptyPost(post))\n\n    if (nonEmptyPosts.length === thread.posts.length) {\n      return {type: 'none', filteredThread: thread}\n    }\n\n    let lastNonEmptyIndex = -1\n    for (let i = thread.posts.length - 1; i >= 0; i--) {\n      if (!isEmptyPost(thread.posts[i])) {\n        lastNonEmptyIndex = i\n        break\n      }\n    }\n\n    const hasNonTrailingEmpty = thread.posts.some(\n      (post, i) => i < lastNonEmptyIndex && isEmptyPost(post),\n    )\n\n    const filteredThread: ThreadDraft = {...thread, posts: nonEmptyPosts}\n\n    return {\n      type: hasNonTrailingEmpty ? 'non-trailing' : 'trailing-only',\n      filteredThread,\n    }\n  }, [thread])\n\n  const onPressPublish = useCallback(async () => {\n    if (isPublishing || isSavingDraft) {\n      return\n    }\n\n    if (!canPost) {\n      return\n    }\n\n    const {type: emptyType, filteredThread} = getFilteredThread()\n\n    if (emptyType === 'non-trailing' && !skipEmptyConfirmedRef.current) {\n      emptyPostsPromptControl.open()\n      return\n    }\n\n    if (\n      filteredThread.posts.some(\n        post =>\n          post.embed.media?.type === 'video' &&\n          post.embed.media.video.asset &&\n          post.embed.media.video.status !== 'done',\n      )\n    ) {\n      setPublishOnUpload(true)\n      return\n    }\n\n    skipEmptyConfirmedRef.current = false\n    setError('')\n    setIsPublishing(true)\n\n    let postUri: string | undefined\n    let postSuccessData: OnPostSuccessData\n    try {\n      logger.info(`composer: posting...`)\n      postUri = (\n        await apilib.post(queryClient, {\n          thread: filteredThread,\n          replyTo: replyTo?.uri,\n          onStateChange: setPublishingStage,\n          langs: currentLanguages,\n          appviewClient: client,\n          chatClient,\n          pdsClient,\n        })\n      ).uris[0]\n\n      // Fire published event for every video that made it into the post.\n      // The status guard upstream ensures each video.telemetry is present and\n      // processing has completed by this point.\n      for (const post of filteredThread.posts) {\n        if (post.embed.media?.type === 'video') {\n          post.embed.media.video.telemetry?.published()\n        }\n      }\n\n      /*\n       * Wait for app view to have received the post(s). If this fails, it's\n       * ok, because the post _was_ actually published above.\n       */\n      try {\n        if (postUri) {\n          logger.info(`composer: waiting for app view`)\n\n          const posts = await retry(\n            5,\n            _e => true,\n            async () => {\n              const res = await client.call(\n                app.bsky.unspecced.getPostThreadV2,\n                {\n                  anchor: postUri! as AtUriString,\n                  above: false,\n                  below: filteredThread.posts.length - 1,\n                  branchingFactor: 1,\n                },\n              )\n              if (res.thread.length !== filteredThread.posts.length) {\n                throw new Error(`composer: app view is not ready`)\n              }\n              if (\n                !res.thread.every(p =>\n                  bsky.isType(app.bsky.unspecced.defs.threadItemPost, p.value),\n                )\n              ) {\n                throw new Error(`composer: app view returned non-post items`)\n              }\n              return res.thread\n            },\n            1e3,\n          )\n          postSuccessData = {\n            replyToUri: replyTo?.uri,\n            posts,\n          }\n        }\n      } catch (waitErr) {\n        logger.info(`composer: waiting for app view failed`, {\n          safeMessage: waitErr,\n        })\n      }\n    } catch (e) {\n      logger.error(e instanceof Error ? e : String(e), {\n        message: `Composer: create post failed`,\n        hasImages: filteredThread.posts.some(\n          p =>\n            p.embed.media?.type === 'images' ||\n            p.embed.media?.type === 'gallery',\n        ),\n      })\n\n      let err = e instanceof Error ? cleanError(e.message) : String(e)\n      if (\n        e instanceof apilib.ReplyDeletedError ||\n        err.includes('not locate record')\n      ) {\n        err = l`We're sorry! The post you are replying to has been deleted.`\n      } else if (e instanceof EmbeddingDisabledError) {\n        err = l`This post's author has disabled quote posts.`\n      }\n      setError(err)\n      setIsPublishing(false)\n      return\n    } finally {\n      if (postUri) {\n        let index = 0\n        for (let post of filteredThread.posts) {\n          ax.metric('post:create', {\n            imageCount:\n              post.embed.media?.type === 'images' ||\n              post.embed.media?.type === 'gallery'\n                ? post.embed.media.images.length\n                : 0,\n            isReply: index > 0 || !!replyTo,\n            isPartOfThread: filteredThread.posts.length > 1,\n            hasLink: !!post.embed.link,\n            hasQuote: !!post.embed.quote,\n            langs: fromPostLanguages(currentLanguages),\n            logContext: 'Composer',\n          })\n          index++\n        }\n      }\n      if (filteredThread.posts.length > 1) {\n        ax.metric('thread:create', {\n          postCount: filteredThread.posts.length,\n          isReply: !!replyTo,\n        })\n      }\n      if (postUri) {\n        for (const q of linkQueries) {\n          const resolved = q.data\n          if (\n            resolved?.type === 'chat-invite' &&\n            bsky.isType(chat.bsky.group.defs.joinLinkPreviewView, resolved.view)\n          ) {\n            ax.metric('groupchat:inviteLink:shared', {\n              convoId: resolved.view.convoId,\n              method: 'post',\n            })\n          }\n        }\n      }\n    }\n    if (postUri && !replyTo) {\n      emitPostCreated()\n    }\n    // Clean up draft and its media after successful publish\n    if (composerState.draftId && composerState.originalLocalRefs) {\n      // Fire draft:post metric\n      if (loadedDraftCreatedAt) {\n        const draftAgeMs = Date.now() - new Date(loadedDraftCreatedAt).getTime()\n        ax.metric('draft:post', {\n          draftAgeMs,\n          wasEdited: composerState.isDirty,\n        })\n      }\n\n      logger.debug('post published, cleaning up draft', {\n        draftId: composerState.draftId,\n        mediaFileCount: composerState.originalLocalRefs.size,\n      })\n      cleanupPublishedDraft({\n        draftId: composerState.draftId,\n        originalLocalRefs: composerState.originalLocalRefs,\n      })\n    }\n    setLangPrefs.savePostLanguageToHistory(fromPostLanguages(currentLanguages))\n    if (initQuote) {\n      // We want to wait for the quote count to update before we call `onPost`, which will refetch data\n      void whenAppViewReady(client, initQuote.uri, res => {\n        const anchor = res?.thread.at(0)\n        if (\n          bsky.isType(app.bsky.unspecced.defs.threadItemPost, anchor?.value) &&\n          anchor.value.post.quoteCount !== initQuote.quoteCount\n        ) {\n          onPost?.(postUri)\n          onPostSuccess?.(postSuccessData)\n          return true\n        }\n        return false\n      })\n    } else {\n      onPost?.(postUri)\n      onPostSuccess?.(postSuccessData)\n    }\n    onClose()\n    setTimeout(() => {\n      Toast.show(\n        <Toast.Outer>\n          <Toast.Icon />\n          <Toast.Text>\n            {filteredThread.posts.length > 1\n              ? l`Your posts were sent`\n              : replyTo\n                ? l`Your reply was sent`\n                : l`Your post was sent`}\n          </Toast.Text>\n          {postUri && (\n            <Toast.Action\n              label={l`View post`}\n              onPress={() => {\n                const {host: name, rkey} = new AtUri(postUri)\n                navigation.navigate('PostThread', {name, rkey})\n              }}>\n              <Trans context=\"Action to view the post the user just created\">\n                View\n              </Trans>\n            </Toast.Action>\n          )}\n        </Toast.Outer>,\n        {type: 'success'},\n      )\n    }, 500)\n  }, [\n    l,\n    ax,\n    client,\n    chatClient,\n    pdsClient,\n    canPost,\n    isPublishing,\n    isSavingDraft,\n    currentLanguages,\n    onClose,\n    onPost,\n    onPostSuccess,\n    initQuote,\n    replyTo,\n    setLangPrefs,\n    queryClient,\n    navigation,\n    composerState.draftId,\n    composerState.originalLocalRefs,\n    composerState.isDirty,\n    cleanupPublishedDraft,\n    loadedDraftCreatedAt,\n    emptyPostsPromptControl,\n    getFilteredThread,\n    linkQueries,\n  ])\n\n  const handleConfirmSkipEmpty = () => {\n    skipEmptyConfirmedRef.current = true\n    void onPressPublish()\n  }\n\n  // Preserves the referential identity passed to each post item.\n  // Avoids re-rendering all posts on each keystroke.\n  const onComposerPostPublish = useNonReactiveCallback(() => {\n    void onPressPublish()\n  })\n\n  useEffect(() => {\n    if (publishOnUpload) {\n      let erroredVideos = 0\n      let uploadingVideos = 0\n      for (let post of thread.posts) {\n        if (isEmptyPost(post)) continue\n        if (post.embed.media?.type === 'video') {\n          const video = post.embed.media.video\n          if (video.status === 'error') {\n            erroredVideos++\n          } else if (video.status !== 'done') {\n            uploadingVideos++\n          }\n        }\n      }\n      if (erroredVideos > 0) {\n        setPublishOnUpload(false)\n      } else if (uploadingVideos === 0) {\n        setPublishOnUpload(false)\n        void onPressPublish()\n      }\n    }\n  }, [thread.posts, onPressPublish, publishOnUpload])\n\n  // TODO: It might make more sense to display this error per-post.\n  // Right now we're just displaying the first one.\n  let erroredVideoPostId: string | undefined\n  let erroredVideo: VideoState | NoVideoState = NO_VIDEO\n  for (let i = 0; i < thread.posts.length; i++) {\n    const post = thread.posts[i]\n    if (\n      post.embed.media?.type === 'video' &&\n      post.embed.media.video.status === 'error'\n    ) {\n      erroredVideoPostId = post.id\n      erroredVideo = post.embed.media.video\n      break\n    }\n  }\n\n  const scrollViewRef = useAnimatedRef<Animated.ScrollView>()\n  useEffect(() => {\n    if (composerState.mutableNeedsFocusActive) {\n      composerState.mutableNeedsFocusActive = false\n      // On Android, this risks getting the cursor stuck behind the keyboard.\n      // Not worth it.\n      if (!IS_ANDROID) {\n        textInputRef.current?.focus()\n      }\n    }\n  }, [composerState])\n\n  useEffect(() => {\n    // Safari ignores `overscroll-behavior`, so horizontal trackpad swipes over\n    // the composer (e.g. on a quote post) can still trigger the browser's\n    // back/forward navigation gesture. Suppress predominantly-horizontal wheel\n    // events so the history-nav gesture never fires. Chrome and Firefox are\n    // covered by the `overscrollBehaviorX: 'contain'` style on the ScrollView.\n    if (!IS_WEB_SAFARI) return\n    const el =\n      scrollViewRef.current?.getScrollableNode() as unknown as HTMLElement | null\n    if (!el) return\n    const onWheel = (e: WheelEvent) => {\n      if (Math.abs(e.deltaX) <= Math.abs(e.deltaY)) return\n      e.preventDefault()\n    }\n    el.addEventListener('wheel', onWheel, {passive: false})\n    return () => el.removeEventListener('wheel', onWheel)\n  }, [scrollViewRef])\n\n  const isLastThreadedPost = thread.posts.length > 1 && nextPost === undefined\n  const {\n    scrollHandler,\n    onScrollViewContentSizeChange,\n    onScrollViewLayout,\n    topBarAnimatedStyle,\n    bottomBarAnimatedStyle,\n  } = useScrollTracker({\n    scrollViewRef,\n    stickyBottom: isLastThreadedPost,\n  })\n\n  const keyboardVerticalOffset = useKeyboardVerticalOffset()\n\n  const footer = (\n    <>\n      <SuggestedLanguage\n        text={activePost.richtext.text}\n        replyToLanguages={replyToLanguages}\n        currentLanguages={currentLanguages}\n        onAcceptSuggestedLanguage={setSelectedPostLanguage}\n        onNudge={onLanguageNudge}\n      />\n      <ComposerPills\n        isReply={!!replyTo}\n        post={activePost}\n        thread={composerState.thread}\n        dispatch={composerDispatch}\n        bottomBarAnimatedStyle={bottomBarAnimatedStyle}\n      />\n      <ComposerFooter\n        post={activePost}\n        dispatch={dispatch}\n        showAddButton={\n          !isEmptyPost(activePost) && (!nextPost || !isEmptyPost(nextPost))\n        }\n        onError={setError}\n        onSelectVideo={selectVideo}\n        onAddPost={() => {\n          composerDispatch({\n            type: 'add_post',\n          })\n        }}\n        currentLanguages={currentLanguages}\n        onSelectLanguage={onSelectLanguage}\n        languageNudgeAt={languageNudgeAt}\n        openGallery={openGallery}\n        textInputRef={textInputRef}\n      />\n    </>\n  )\n\n  const IS_WEBFooterSticky = !IS_NATIVE && thread.posts.length > 1\n  return (\n    <BottomSheetPortalProvider>\n      <KeyboardAvoidingView\n        testID=\"composePostView\"\n        behavior={IS_IOS ? 'padding' : 'height'}\n        keyboardVerticalOffset={keyboardVerticalOffset}\n        automaticOffset={IS_IPAD}\n        style={a.flex_1}>\n        <View\n          style={[a.flex_1, viewStyles]}\n          aria-modal\n          accessibilityViewIsModal>\n          <ComposerTopBar\n            canPost={canPost}\n            isReply={!!replyTo}\n            isPublishQueued={publishOnUpload}\n            isPublishing={isPublishing}\n            isSavingDraft={isSavingDraft}\n            isThread={thread.posts.length > 1}\n            publishingStage={publishingStage}\n            topBarAnimatedStyle={topBarAnimatedStyle}\n            onCancel={onPressCancel}\n            onPublish={() => void onPressPublish()}\n            onSelectDraft={draft => void handleSelectDraft(draft)}\n            onSaveDraft={saveCurrentDraft}\n            onDiscard={handleClearComposer}\n            isEmpty={isComposerEmpty}\n            isDirty={composerState.isDirty}\n            isEditingDraft={!!composerState.draftId}\n            canSaveDraft={allPostsWithinLimit}\n            textLength={thread.posts[0].richtext.text.length}>\n            {missingAltError && <AltTextReminder error={missingAltError} />}\n            <ErrorBanner\n              error={error}\n              videoState={erroredVideo}\n              clearError={() => setError('')}\n              clearVideo={\n                erroredVideoPostId\n                  ? () => clearVideo(erroredVideoPostId)\n                  : () => {}\n              }\n            />\n          </ComposerTopBar>\n\n          <Animated.ScrollView\n            ref={scrollViewRef}\n            onScroll={scrollHandler}\n            contentContainerStyle={a.flex_grow}\n            style={[\n              a.flex_1,\n              web({\n                scrollbarGutter: 'stable',\n                scrollbarColor: `${t.palette.contrast_200} transparent`,\n                // Prevent horizontal trackpad swipes from triggering the\n                // browser's back/forward overscroll-navigation gesture.\n                // Handles Chrome and Firefox; Safari is handled separately\n                // via a wheel listener since it ignores overscroll-behavior.\n                overscrollBehaviorX: 'contain',\n              }),\n            ]}\n            keyboardShouldPersistTaps=\"always\"\n            onContentSizeChange={onScrollViewContentSizeChange}\n            onLayout={onScrollViewLayout}>\n            {replyTo ? <ComposerReplyTo replyTo={replyTo} /> : undefined}\n            {thread.posts.map((post, index) => (\n              <Fragment key={post.id + (composerState.draftId ?? '')}>\n                <ComposerPost\n                  post={post}\n                  dispatch={composerDispatch}\n                  textInputRef={post.id === activePost.id ? textInputRef : null}\n                  isFirstPost={index === 0}\n                  isLastPost={index === thread.posts.length - 1}\n                  isPartOfThread={thread.posts.length > 1}\n                  isReply={index > 0 || !!replyTo}\n                  isActive={post.id === activePost.id}\n                  canRemovePost={thread.posts.length > 1}\n                  canRemoveQuote={index > 0 || !initQuote}\n                  onSelectVideo={selectVideo}\n                  onClearVideo={clearVideo}\n                  onPublish={onComposerPostPublish}\n                  onError={setError}\n                />\n                {IS_WEBFooterSticky && post.id === activePost.id && (\n                  <View style={styles.stickyFooterWeb}>{footer}</View>\n                )}\n              </Fragment>\n            ))}\n          </Animated.ScrollView>\n          {!IS_WEBFooterSticky && footer}\n        </View>\n\n        {replyTo ? (\n          <Prompt.Basic\n            control={discardPromptControl}\n            title={l`Discard draft?`}\n            description=\"\"\n            confirmButtonCta={l`Discard`}\n            confirmButtonColor=\"negative\"\n            onConfirm={handleDiscard}\n          />\n        ) : (\n          <Prompt.Outer control={discardPromptControl}>\n            <Prompt.Content>\n              <Prompt.TitleText>\n                {allPostsWithinLimit ? (\n                  composerState.draftId ? (\n                    <Trans>Save changes?</Trans>\n                  ) : (\n                    <Trans>Save draft?</Trans>\n                  )\n                ) : (\n                  <Trans>Discard post?</Trans>\n                )}\n              </Prompt.TitleText>\n              <Prompt.DescriptionText>\n                {allPostsWithinLimit ? (\n                  composerState.draftId ? (\n                    <Trans>\n                      You have unsaved changes to this draft, would you like to\n                      save them?\n                    </Trans>\n                  ) : (\n                    <Trans>\n                      Would you like to save this as a draft to edit later?\n                    </Trans>\n                  )\n                ) : (\n                  <Trans>You can only save drafts up to 1000 characters.</Trans>\n                )}\n              </Prompt.DescriptionText>\n            </Prompt.Content>\n            <Prompt.Actions>\n              {allPostsWithinLimit && (\n                <Prompt.Action\n                  cta={composerState.draftId ? l`Save changes` : l`Save draft`}\n                  onPress={() => void handleSaveDraft()}\n                  color=\"primary\"\n                />\n              )}\n              <Prompt.Cancel cta={l`Keep editing`} />\n              <Prompt.Action\n                cta={l`Discard`}\n                onPress={handleDiscard}\n                color=\"negative_subtle\"\n              />\n            </Prompt.Actions>\n          </Prompt.Outer>\n        )}\n\n        <Prompt.Basic\n          control={emptyPostsPromptControl}\n          title={l`Skip empty posts?`}\n          description={l`Your thread has empty posts that will be skipped. The remaining posts will be published as a thread.`}\n          confirmButtonCta={l`Post anyway`}\n          cancelButtonCta={l`Keep editing`}\n          onConfirm={handleConfirmSkipEmpty}\n        />\n      </KeyboardAvoidingView>\n    </BottomSheetPortalProvider>\n  )\n}","file":"src/view/com/composer/Composer.tsx","kind":"component","line":254,"members":{"allPostsWithinLimit":[428,430],"ax":[272,272],"cancelRef":[254,269],"chatClient":[274,274],"clearVideo":[554,565],"client":[273,273],"composerState":[361,371],"currentLanguages":[330,336],"discardPromptControl":[289,289],"dispatch":[435,444],"emptyPostsPromptControl":[290,290],"error":[301,301],"getDraftSaveError":[784,794],"getFilteredThread":[1048,1076],"handleClearComposer":[918,923],"handleConfirmSkipEmpty":[1341,1344],"handleDiscard":[883,897],"handleSaveDraft":[809,853],"handleSelectDraft":[711,769],"hasUnavailableChatInvite":[1028,1032],"initImageUris":[254,269],"initMention":[254,269],"initQuote":[254,269],"initQuoteUri":[254,269],"initText":[254,269],"initVideoUri":[254,269],"insets":[925,925],"isComposerEmpty":[900,915],"isPublishing":[299,299],"keyboardVerticalOffset":[1434,1434],"langPrefs":[286,286],"languageNudgeAt":[353,353],"linkQueries":[1022,1027],"linkUris":[1019,1021],"loadedDraftCreatedAt":[307,309],"logContext":[254,269],"missingAltError":[989,1014],"navigation":[297,297],"onClose":[773,782],"onComposerPostPublish":[1348,1350],"onInitVideo":[534,538],"onLanguageNudge":[354,359],"onPost":[254,269],"onPostSuccess":[254,269],"onPressCancel":[934,965],"onPressPublish":[1078,1339],"onSelectLanguage":[342,345],"openGallery":[254,269],"pdsClient":[275,275],"publishOnUpload":[771,771],"publishingStage":[300,300],"queryClient":[276,276],"replyTo":[254,269],"replyToLanguages":[322,324],"requireAltTextEnabled":[285,285],"restoreVideo":[567,709],"saveCurrentDraft":[856,880],"scrollViewRef":[1392,1392],"selectVideo":[446,532],"selectedPostLanguage":[315,317],"setLangPrefs":[287,287],"skipEmptyConfirmedRef":[291,291],"t":[271,271],"textInputRef":[288,288],"uncheckedQuoteUri":[380,382],"validateDraftTextOrError":[796,807],"viewStyles":[926,932]},"supers":[]},"FeedAPI":{"alsoIn":["src/features/followingV2/home/api/types.ts"],"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"],["index","h-services","Services \u00b7 what the screens share"]],"code":"export interface FeedAPI {\n  peekLatest(): Promise<app.bsky.feed.defs.FeedViewPost>\n  fetch({\n    cursor,\n    limit,\n    signal,\n  }: {\n    cursor: string | undefined\n    limit: number\n    signal?: AbortSignal\n  }): Promise<FeedAPIResponse>\n}","file":"src/lib/api/feed/types.ts","kind":"interface","line":8,"members":{"fetch":[10,18],"peekLatest":[9,9]},"supers":[]},"InnerApp":{"alsoIn":["src/App.web.tsx"],"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["launch","h-classes","Logic \u00b7 class diagram"],["launch","h-sequence","Cold start \u00b7 sequence"]],"code":"function InnerApp() {\n  const [isReady, setIsReady] = useState(false)\n  const {currentAccount} = useSession()\n  const {resumeSession} = useSessionApi()\n  const theme = useColorModeTheme()\n  const {t: l} = useLingui()\n  const hasCheckedLanding = useLandingEntry()\n\n  // init\n  useEffect(() => {\n    async function onLaunch(account?: SessionAccount) {\n      try {\n        if (account) {\n          await resumeSession(account)\n        } else {\n          await features.init\n        }\n      } catch (e) {\n        logger.warn(`session: resume failed`, {message: e})\n      }\n      setIsReady(true)\n    }\n    const account = readLastActiveAccount()\n    void onLaunch(account)\n  }, [resumeSession])\n\n  useEffect(() => {\n    return listenSessionDropped(() => {\n      Toast.show(l`Sorry! Your session expired. Please sign in again.`, {\n        type: 'info',\n      })\n    })\n  }, [l])\n\n  return (\n    <Alf theme={theme}>\n      <ThemeProvider theme={theme}>\n        <ContextMenuProvider>\n          <Splash isReady={isReady && hasCheckedLanding}>\n            <VideoVolumeProvider>\n              <GestureHandlerRootView style={a.h_full}>\n                <Fragment\n                  // Resets the entire tree below when it changes:\n                  key={currentAccount?.did}>\n                  <AnalyticsFeaturesContext>\n                    <QueryProvider currentDid={currentAccount?.did}>\n                      <BetaUserStorageSync />\n                      <PolicyUpdateOverlayProvider>\n                        <LiveEventsProvider>\n                          <AgeAssuranceV2Provider>\n                            <ComposerProvider>\n                              <MessagesProvider>\n                                {/* LabelDefsProvider MUST come before ModerationOptsProvider */}\n                                <LabelDefsProvider>\n                                  <ModerationOptsProvider>\n                                    <LoggedOutViewProvider>\n                                      <SelectedFeedProvider>\n                                        <HiddenRepliesProvider>\n                                          <HomeBadgeProvider>\n                                            <UnreadNotifsProvider>\n                                              <BackgroundNotificationPreferencesProvider>\n                                                <MutedThreadsProvider>\n                                                  <ProgressGuideProvider>\n                                                    <ServiceAccountManager>\n                                                      <TrendingTopicsWidgetSync />\n                                                      <EmailVerificationProvider>\n                                                        <HideBottomBarBorderProvider>\n                                                          <GlobalGestureEventsProvider>\n                                                            <IntentDialogProvider>\n                                                              <TranslateOnDeviceProvider>\n                                                                <TestCtrls />\n                                                                <Shell />\n                                                              </TranslateOnDeviceProvider>\n                                                            </IntentDialogProvider>\n                                                          </GlobalGestureEventsProvider>\n                                                        </HideBottomBarBorderProvider>\n                                                      </EmailVerificationProvider>\n                                                    </ServiceAccountManager>\n                                                  </ProgressGuideProvider>\n                                                </MutedThreadsProvider>\n                                              </BackgroundNotificationPreferencesProvider>\n                                            </UnreadNotifsProvider>\n                                          </HomeBadgeProvider>\n                                        </HiddenRepliesProvider>\n                                      </SelectedFeedProvider>\n                                    </LoggedOutViewProvider>\n                                  </ModerationOptsProvider>\n                                </LabelDefsProvider>\n                              </MessagesProvider>\n                            </ComposerProvider>\n                          </AgeAssuranceV2Provider>\n                        </LiveEventsProvider>\n                      </PolicyUpdateOverlayProvider>\n                    </QueryProvider>\n                  </AnalyticsFeaturesContext>\n                </Fragment>\n                <ToastOutlet />\n              </GestureHandlerRootView>\n            </VideoVolumeProvider>\n          </Splash>\n        </ContextMenuProvider>\n      </ThemeProvider>\n    </Alf>\n  )\n}","file":"src/App.tsx","kind":"component","line":111,"members":{"hasCheckedLanding":[117,117],"isReady":[112,112],"theme":[115,115]},"shot":"shots/code/InnerApp.jpg","supers":[]},"LoginForm":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["sign-in","h-classes","Logic \u00b7 class diagram"],["sign-in","h-widgets","Screen \u00b7 component composition"],["sign-in","h-sequence","Sign in \u00b7 sequence"]],"code":"export const LoginForm = ({\n  error,\n  serviceUrl,\n  serviceDescription,\n  initialHandle,\n  setError,\n  setServiceUrl,\n  onPressRetryConnect,\n  onPressBack,\n  onPressForgotPassword,\n  onAttemptSuccess,\n  onAttemptFailed,\n  onPressCreateAccount,\n}: {\n  error: string\n  serviceUrl: string\n  serviceDescription: ServiceDescription | undefined\n  initialHandle: string\n  setError: (v: string) => void\n  setServiceUrl: (v: string) => void\n  onPressRetryConnect: () => void\n  onPressBack: () => void\n  onPressForgotPassword: () => void\n  onAttemptSuccess: () => void\n  onAttemptFailed: () => void\n  onPressCreateAccount: () => void\n}) => {\n  const t = useTheme()\n  const [isProcessing, setIsProcessing] = useState(false)\n  const [errorField, setErrorField] = useState<\n    'none' | 'identifier' | 'password' | '2fa'\n  >('none')\n  const [isAuthFactorTokenNeeded, setIsAuthFactorTokenNeeded] = useState(false)\n  const [showResolveError, setShowResolveError] = useState(false)\n  const [identifier, setIdentifier] = useState(initialHandle || '')\n  const [password, setPassword] = useState('')\n  const [identifierFocused, setIdentifierFocused] = useState(false)\n  const [authFactorToken, setAuthFactorToken] = useState('')\n  const identifierRef = useRef<React.ComponentRef<typeof TextInput>>(null)\n  const passwordRef = useRef<React.ComponentRef<typeof TextInput>>(null)\n  const hasFocusedOnce = useRef(false)\n  const {t: l} = useLingui()\n  const {login} = useSessionApi()\n  const {accounts} = useSession()\n  const requestNotificationsPermission = useRequestNotificationsPermission()\n  const {setShowLoggedOut} = useLoggedOutViewControls()\n  const setHasCheckedForStarterPack = useSetHasCheckedForStarterPack()\n  const serverInputControl = useDialogControl()\n  const confirmHostingProviderControl = useDialogControl()\n  const [pendingLogin, setPendingLogin] = useState<{\n    service: string\n    fullIdent: string\n    passwordLength: number\n  } | null>(null)\n  const hostingProvider = useHostingProvider({\n    identifier,\n    defaultService: serviceUrl,\n  })\n  const {gtMobile} = useBreakpoints()\n\n  /*\n   * Surface an inline error on the username field only once detection has\n   * settled on an unresolvable identifier and the user has moved on from the\n   * field. Hidden while focused so we don't nag mid-type, and it clears\n   * automatically when the identifier resolves or an override is set (both\n   * move `state.status` away from 'unresolved').\n   */\n  const showUnresolvedError =\n    hostingProvider.state.status === 'unresolved' && !identifierFocused\n\n  /**\n   * Performs the actual login attempt against a resolved service. Reads the\n   * password and 2FA token from the current form state, and manages\n   * `setIsProcessing` itself: it stays processing on success (the app\n   * transitions away) and clears it on any failure.\n   */\n  const attemptLogin = async (service: string, fullIdent: string) => {\n    setIsProcessing(true)\n\n    try {\n      // TODO remove double login\n      await login(\n        {\n          service,\n          identifier: fullIdent,\n          password,\n          authFactorToken:\n            checkAndFormatResetCode(authFactorToken) || authFactorToken.trim(),\n        },\n        'LoginForm',\n      )\n      onAttemptSuccess()\n      setShowLoggedOut(false)\n      setHasCheckedForStarterPack(true)\n      void requestNotificationsPermission('Login')\n    } catch (err) {\n      const errMsg = String(err)\n      setIsProcessing(false)\n      /*\n       * `LexAuthFactorError` is what `PasswordSession.login` throws when the\n       * server demands an email 2FA token.\n       */\n      if (err instanceof LexAuthFactorError) {\n        setIsAuthFactorTokenNeeded(true)\n      } else {\n        onAttemptFailed()\n        if (errMsg.includes('Token is invalid')) {\n          logger.debug('Failed to login due to invalid 2fa token', {\n            error: errMsg,\n          })\n          setError(l`Invalid 2FA confirmation code.`)\n          setErrorField('2fa')\n        } else if (\n          errMsg.includes('Authentication Required') ||\n          errMsg.includes('Invalid identifier or password')\n        ) {\n          logger.debug('Failed to login due to invalid credentials', {\n            error: errMsg,\n          })\n          setError(l`Incorrect username or password`)\n        } else if (isNetworkError(err)) {\n          logger.warn('Failed to login due to network error', {error: errMsg})\n          setError(\n            l`Unable to contact your service. Please check your Internet connection.`,\n          )\n        } else {\n          logger.warn('Failed to login', {error: errMsg})\n          /* the error object, not its stringification: cleanError only\n           * extracts the clean server message from a live LexError */\n          setError(cleanError(err))\n        }\n      }\n    }\n  }\n\n  const onPressNext = async () => {\n    if (isProcessing) return\n    Keyboard.dismiss()\n    setError('')\n    setErrorField('none')\n    setShowResolveError(false)\n\n    const normalizedIdentifier = identifier.toLowerCase().trim()\n\n    if (!normalizedIdentifier) {\n      setError(l`Please enter your username`)\n      setErrorField('identifier')\n      return\n    }\n\n    if (!password) {\n      setError(l`Please enter your password`)\n      setErrorField('password')\n      return\n    }\n\n    setIsProcessing(true)\n\n    // try to guess the handle if the user just gave their own username\n    let fullIdent = normalizedIdentifier\n    if (\n      !normalizedIdentifier.includes('@') && // not an email\n      !normalizedIdentifier.includes('.') && // not a domain\n      !normalizedIdentifier.startsWith('did:') && // not a DID\n      serviceDescription &&\n      serviceDescription.availableUserDomains.length > 0\n    ) {\n      let matched = false\n      for (const domain of serviceDescription.availableUserDomains) {\n        if (fullIdent.endsWith(domain)) {\n          matched = true\n        }\n      }\n      if (!matched) {\n        fullIdent = createFullHandle(\n          normalizedIdentifier,\n          serviceDescription.availableUserDomains[0],\n        )\n      }\n    }\n\n    /*\n     * Await autodetection against the current identifier before logging in.\n     * If detection is still in flight this waits for it (bypassing the\n     * debounce); otherwise it resolves near-instantly from cache. Falls back\n     * to the default service on anything unresolvable, but a network error\n     * throws - in that case we must NOT log in, since we can't be sure which\n     * server to send the password to.\n     */\n    let service: string\n    let did: string | null\n    try {\n      ;({service, did} =\n        await hostingProvider.resolveService(normalizedIdentifier))\n    } catch (err) {\n      logger.debug('Failed to resolve hosting provider', {error: String(err)})\n      setIsProcessing(false)\n      setShowResolveError(true)\n      return\n    }\n\n    /*\n     * If detection landed on a non-Bluesky server, confirm before sending the\n     * password, to guard against typosquatted handles capturing credentials. A\n     * manual override is skipped: choosing a server by hand is explicit user\n     * consent, so only auto-detected hosts need the guard. An identity the\n     * user has signed into on this device before is also trusted: a\n     * typosquatted handle would resolve to the attacker's different DID, so\n     * DID membership in the account list is the correct skip condition\n     * (handles and hosts are not stable keys - service URLs drift and pdsUrl\n     * is often unset).\n     */\n    const isKnownAccount =\n      did != null && accounts.some(account => account.did === did)\n    const needsConfirmation =\n      !isBlueskyHostedUrl(service) &&\n      hostingProvider.state.status !== 'overridden' &&\n      !isKnownAccount\n\n    if (needsConfirmation) {\n      setIsProcessing(false)\n      setPendingLogin({service, fullIdent, passwordLength: password.length})\n      confirmHostingProviderControl.open()\n      return\n    }\n\n    await attemptLogin(service, fullIdent)\n  }\n\n  return (\n    <FormContainer testID=\"loginForm\" titleText={<Trans>Sign in</Trans>}>\n      <HostingProviderDialog\n        control={serverInputControl}\n        currentOverride={\n          hostingProvider.state.status === 'overridden'\n            ? hostingProvider.state.pdsUrl\n            : null\n        }\n        isEmail={hostingProvider.state.status === 'email'}\n        onSelectManual={url => {\n          hostingProvider.override(url)\n          setServiceUrl(url)\n        }}\n        onSelectAutomatic={() => {\n          hostingProvider.clearOverride()\n          setServiceUrl(DEFAULT_SERVICE)\n        }}\n      />\n      <ConfirmHostingProviderDialog\n        control={confirmHostingProviderControl}\n        host={toNiceHostingUrl(pendingLogin?.service ?? '')}\n        identifier={pendingLogin?.fullIdent ?? ''}\n        passwordLength={pendingLogin?.passwordLength ?? 0}\n        onConfirm={() => {\n          if (pendingLogin) {\n            void attemptLogin(pendingLogin.service, pendingLogin.fullIdent)\n          }\n        }}\n      />\n      <View>\n        <TextField.LabelText>\n          <Trans>Username or email</Trans>\n        </TextField.LabelText>\n        <TextField.Root\n          isInvalid={errorField === 'identifier' || showUnresolvedError}>\n          <TextField.Icon\n            icon={hostingProvider.state.status === 'email' ? EmailIcon : AtIcon}\n          />\n          <TextField.Input\n            testID=\"loginUsernameInput\"\n            inputRef={identifierRef}\n            label={l`Username or email address`}\n            placeholder={null}\n            autoCapitalize=\"none\"\n            autoFocus={!IS_IOS && !initialHandle}\n            autoCorrect={false}\n            autoComplete=\"username\"\n            returnKeyType=\"next\"\n            textContentType=\"username\"\n            value={identifier}\n            onChangeText={v => {\n              setIdentifier(v)\n              if (errorField) setErrorField('none')\n              if (showResolveError) setShowResolveError(false)\n            }}\n            onFocus={() => setIdentifierFocused(true)}\n            onBlur={() => setIdentifierFocused(false)}\n            onSubmitEditing={() => {\n              passwordRef.current?.focus()\n            }}\n            blurOnSubmit={false} // prevents flickering due to onSubmitEditing going to next field\n            editable={!isProcessing}\n            accessibilityHint={l`Enter the username or email address you used when you created your account`}\n          />\n        </TextField.Root>\n        {showUnresolvedError && (\n          <Text\n            style={[\n              a.text_sm,\n              a.leading_snug,\n              a.mt_sm,\n              {color: t.palette.negative_500},\n            ]}>\n            <Trans>\n              We couldn't find an account with that username. Please check that\n              you've typed it correctly, or{' '}\n              <InlineLinkText\n                label={l`set your hosting provider manually`}\n                style={[a.text_sm, a.leading_snug]}\n                {...createStaticClick(() => serverInputControl.open())}>\n                set your hosting provider manually\n              </InlineLinkText>\n              .\n            </Trans>\n          </Text>\n        )}\n      </View>\n\n      <View>\n        <TextField.LabelText>\n          <Trans>Password</Trans>\n        </TextField.LabelText>\n        <PasswordField\n          isInvalid={errorField === 'password'}\n          testID=\"loginPasswordInput\"\n          inputRef={passwordRef}\n          label={l`Password`}\n          placeholder={null}\n          autoFocus={!IS_IOS && !!initialHandle}\n          autoComplete=\"current-password\"\n          returnKeyType=\"done\"\n          enablesReturnKeyAutomatically={true}\n          value={password}\n          onChangeText={v => {\n            setPassword(v)\n            if (errorField) setErrorField('none')\n          }}\n          onSubmitEditing={() => void onPressNext()}\n          blurOnSubmit={false} // HACK: https://github.com/facebook/react-native/issues/21911#issuecomment-558343069 Keyboard blur behavior is now handled in onSubmitEditing\n          editable={!isProcessing}\n          accessibilityHint={l`Enter your password`}\n          onLayout={\n            IS_IOS\n              ? () => {\n                  if (hasFocusedOnce.current) return\n                  hasFocusedOnce.current = true\n                  // kinda dumb, but if we use `autoFocus` to focus an\n                  // input, it happens before the password input gets\n                  // rendered. this breaks the password autofill on iOS (it\n                  // only does the username part). delaying it until both\n                  // inputs are rendered fixes the autofill. when a handle is\n                  // prefilled we focus the password field directly so the\n                  // user can go straight to typing it -sfn\n                  if (initialHandle) {\n                    passwordRef.current?.focus()\n                  } else {\n                    identifierRef.current?.focus()\n                  }\n                }\n              : undefined\n          }\n        />\n\n        {!isAuthFactorTokenNeeded && (\n          <Button\n            label={l`Forgot password?`}\n            accessibilityHint={l`Reset your password by sending a code to your email`}\n            style={[a.mt_md, a.self_start]}\n            hoverStyle={{opacity: 0.5}}\n            hitSlop={HITSLOP_10}\n            onPress={onPressForgotPassword}>\n            <ButtonText style={[t.atoms.text_contrast_medium]}>\n              <Trans>Forgot password?</Trans>\n            </ButtonText>\n          </Button>\n        )}\n      </View>\n      {isAuthFactorTokenNeeded && (\n        <View>\n          <TextField.LabelText>\n            <Trans>2FA Confirmation</Trans>\n          </TextField.LabelText>\n          <TokenField\n            testID=\"loginAuthFactorTokenInput\"\n            autoFocus\n            autoComplete=\"one-time-code\"\n            returnKeyType=\"done\"\n            blurOnSubmit={false} // prevents flickering due to onSubmitEditing going to next field\n            value={authFactorToken}\n            onChangeText={text => {\n              setAuthFactorToken(text)\n              if (errorField) setErrorField('none')\n            }}\n            onSubmitEditing={() => void onPressNext()}\n            editable={!isProcessing}\n            isInvalid={errorField === '2fa'}\n            accessibilityHint={l`Enter the code from your email or authenticator app`}\n          />\n          <Text style={[a.text_sm, t.atoms.text_contrast_medium, a.mt_sm]}>\n            <Trans>\n              Enter the sign in code from your email or authenticator app.\n            </Trans>\n          </Text>\n        </View>\n      )}\n\n      {/*\n       * At most one error is visible at a time. The inline username error\n       * (under the field) wins; otherwise the resolution-failure error takes\n       * precedence over the generic form error.\n       */}\n      {!showUnresolvedError &&\n        (showResolveError ? (\n          <Admonition.Outer type=\"error\">\n            <Admonition.Row>\n              <Admonition.Icon />\n              <Admonition.Content>\n                <Admonition.Text>\n                  <Trans>\n                    We couldn\u2019t verify your hosting provider. Check your\n                    internet connection, or{' '}\n                    <InlineLinkText\n                      label={l`Set your hosting provider manually`}\n                      style={[a.text_sm, a.leading_snug]}\n                      {...createStaticClick(() => serverInputControl.open())}>\n                      set your hosting provider manually\n                    </InlineLinkText>\n                    .\n                  </Trans>\n                </Admonition.Text>\n              </Admonition.Content>\n            </Admonition.Row>\n          </Admonition.Outer>\n        ) : (\n          error && (\n            <Admonition.Admonition type=\"error\">{error}</Admonition.Admonition>\n          )\n        ))}\n\n      <View\n        style={[\n          a.pt_md,\n          gtMobile && [a.justify_between, a.flex_row, a.gap_sm],\n        ]}>\n        {gtMobile && (\n          <>\n            <Button\n              label={l`Back`}\n              color=\"secondary\"\n              size=\"large\"\n              onPress={onPressBack}>\n              <ButtonText>\n                <Trans>Back</Trans>\n              </ButtonText>\n            </Button>\n\n            <View style={[a.flex_shrink, a.justify_center, a.ml_auto]}>\n              <HostingProviderIndicator\n                state={hostingProvider.state}\n                onPress={() => serverInputControl.open()}\n              />\n            </View>\n          </>\n        )}\n        {!serviceDescription && error ? (\n          <Button\n            testID=\"loginRetryButton\"\n            label={l`Retry`}\n            accessibilityHint={l`Retries signing in`}\n            color=\"primary_subtle\"\n            size=\"large\"\n            onPress={onPressRetryConnect}>\n            <ButtonText>\n              <Trans>Retry</Trans>\n            </ButtonText>\n          </Button>\n        ) : !serviceDescription ? (\n          <Button\n            label={l`Connecting to service\u2026`}\n            size=\"large\"\n            color=\"secondary\"\n            disabled>\n            <ButtonIcon icon={Loader} />\n            <ButtonText>\n              <Trans>Connecting\u2026</Trans>\n            </ButtonText>\n          </Button>\n        ) : (\n          <Button\n            testID=\"loginNextButton\"\n            label={l`Sign in`}\n            accessibilityHint={l`Navigates to the next screen`}\n            color=\"primary\"\n            size=\"large\"\n            onPress={() => void onPressNext()}>\n            <ButtonText>\n              <Trans>Sign in</Trans>\n            </ButtonText>\n            {isProcessing && <ButtonIcon icon={Loader} />}\n          </Button>\n        )}\n      </View>\n\n      {IS_NATIVE && (\n        <Text style={[a.text_md, native([a.text_center, a.mx_auto]), a.mt_sm]}>\n          <Trans>\n            New to Bluesky?{' '}\n            <InlineLinkText\n              label={l`Sign up`}\n              style={[a.text_md, native(a.text_center)]}\n              {...createStaticClick(() => onPressCreateAccount())}>\n              Sign up\n            </InlineLinkText>\n          </Trans>\n        </Text>\n      )}\n\n      {!gtMobile && (\n        <HostingProviderIndicator\n          state={hostingProvider.state}\n          onPress={() => serverInputControl.open()}\n        />\n      )}\n    </FormContainer>\n  )\n}","file":"src/screens/Login/LoginForm.tsx","kind":"component","line":41,"members":{"attemptLogin":[117,174],"authFactorToken":[78,78],"confirmHostingProviderControl":[89,89],"error":[41,67],"errorField":[70,72],"hasFocusedOnce":[81,81],"hostingProvider":[95,98],"identifier":[75,75],"identifierFocused":[77,77],"identifierRef":[79,79],"initialHandle":[41,67],"isAuthFactorTokenNeeded":[73,73],"isProcessing":[69,69],"onAttemptFailed":[41,67],"onAttemptSuccess":[41,67],"onPressBack":[41,67],"onPressCreateAccount":[41,67],"onPressForgotPassword":[41,67],"onPressNext":[176,268],"onPressRetryConnect":[41,67],"password":[76,76],"passwordRef":[80,80],"pendingLogin":[90,94],"requestNotificationsPermission":[85,85],"serverInputControl":[88,88],"serviceDescription":[41,67],"serviceUrl":[41,67],"setError":[41,67],"setHasCheckedForStarterPack":[87,87],"setServiceUrl":[41,67],"showResolveError":[74,74],"t":[68,68]},"shot":"shots/code/LoginForm.jpg","supers":[]},"NativeSplashScreen":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["launch","h-widgets","Screen \u00b7 component composition"]],"code":"export function NativeSplashScreen({\n  onPressSignin,\n  onPressCreateAccount,\n}: {\n  onPressSignin: () => void\n  onPressCreateAccount: () => void\n}) {\n  const t = useTheme()\n  const {gtPhone} = useBreakpoints()\n  const {_} = useLingui()\n  const isDarkMode = t.name !== 'light'\n\n  const haptics = useHaptics()\n\n  /*\n   * The root frame is right on the first render, so phones never flash the\n   * safe art. After that, follow the measured size: on web the frame doesn't\n   * update when the window is resized.\n   */\n  const frame = useSafeAreaFrame()\n  const [size, setSize] = useState<{width: number; height: number}>()\n  const {width, height} = size ?? frame\n  const isPhoneShaped = width / height <= MAX_PHONE_ART_ASPECT_RATIO\n\n  const styles = useMemo(() => {\n    const logoFill = isDarkMode ? 'white' : t.palette.primary_500\n    return {\n      logoFill,\n      logoShadow: isDarkMode\n        ? [\n            {\n              shadowColor: logoFill,\n              shadowRadius: 8,\n              shadowOpacity: 0.5,\n              shadowOffset: {\n                width: 0,\n                height: 0,\n              },\n            },\n          ]\n        : [],\n    }\n  }, [t, isDarkMode])\n\n  return (\n    <>\n      <View\n        style={[a.absolute, a.inset_0]}\n        onLayout={evt => {\n          const layout = evt.nativeEvent.layout\n          if (layout.width > 0 && layout.height > 0) {\n            setSize({width: layout.width, height: layout.height})\n          }\n        }}>\n        <Image\n          accessibilityIgnoresInvertColors\n          source={\n            ART[isPhoneShaped ? 'phone' : 'safe'][isDarkMode ? 'dark' : 'light']\n          }\n          contentPosition={isPhoneShaped ? 'center' : SAFE_ART_POSITION}\n          style={[a.absolute, a.inset_0]}\n        />\n      </View>\n\n      <Animated.View\n        entering={FadeIn.duration(90)}\n        exiting={FadeOut.duration(90)}\n        style={[a.flex_1]}>\n        <View\n          style={[a.justify_center, a.align_center, {gap: 6, paddingTop: 46}]}>\n          <Logo width={76} fill={styles.logoFill} style={styles.logoShadow} />\n          <Logotype\n            width={91}\n            fill={styles.logoFill}\n            style={styles.logoShadow}\n          />\n        </View>\n\n        <View style={[a.flex_1]} />\n\n        <View\n          testID=\"signinOrCreateAccount\"\n          style={[\n            a.px_5xl,\n            a.gap_md,\n            isPhoneShaped ? a.pb_sm : a.pb_xl,\n            gtPhone && [a.w_full, a.self_center, {maxWidth: 600}],\n          ]}>\n          <Button\n            testID=\"createAccountButton\"\n            onPress={() => {\n              onPressCreateAccount()\n              haptics.tap()\n            }}\n            label={_(msg`Create new account`)}\n            accessibilityHint={_(\n              msg`Opens flow to create a new Bluesky account`,\n            )}\n            size=\"large\"\n            color={isDarkMode ? 'secondary_inverted' : 'secondary'}\n            style={[\n              {\n                shadowColor: t.palette.black,\n                shadowRadius: 8,\n                shadowOpacity: 0.1,\n                shadowOffset: {\n                  width: 0,\n                  height: 5,\n                },\n                elevation: 16,\n              },\n            ]}>\n            <ButtonText>\n              <Trans>Create account</Trans>\n            </ButtonText>\n          </Button>\n\n          <Button\n            testID=\"signInButton\"\n            onPress={() => {\n              onPressSignin()\n              haptics.tap()\n            }}\n            label={_(msg`Sign in`)}\n            accessibilityHint={_(\n              msg`Opens flow to sign in to your existing Bluesky account`,\n            )}\n            size=\"large\"\n            /*\n             * Only the phone art has flat ground under this button, so\n             * elsewhere it gets the same dark glass as the lightbox chrome to\n             * stay legible over the busy part of the illustration. The fill\n             * goes on the button because the web BlurView overrides its own.\n             */\n            style={\n              !isPhoneShaped && [\n                a.overflow_hidden,\n                {backgroundColor: 'rgba(0, 0, 0, 0.5)'},\n              ]\n            }\n            hoverStyle={{opacity: 0.5}}>\n            {!isPhoneShaped && (\n              <BlurView\n                intensity={20}\n                tint=\"dark\"\n                style={[a.absolute, a.inset_0]}\n              />\n            )}\n            <ButtonText style={{color: 'white'}}>\n              <Trans>Sign in</Trans>\n            </ButtonText>\n          </Button>\n        </View>\n      </Animated.View>\n    </>\n  )\n}","file":"src/view/com/auth/NativeSplashScreen.tsx","kind":"component","line":45,"members":{"frame":[64,64],"haptics":[57,57],"onPressCreateAccount":[45,51],"onPressSignin":[45,51],"size":[65,65],"styles":[69,87],"t":[52,52]},"shot":"shots/code/NativeSplashScreen.jpg","supers":[]},"NotificationsScreen":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["notifications","h-widgets","Screen \u00b7 component composition"]],"code":"export function NotificationsScreen({}: Props) {\n  const {t: l} = useLingui()\n  const t = useTheme()\n  const {openComposer} = useOpenComposer()\n\n  return (\n    <Layout.Screen testID=\"notificationsScreen\" noInsetTop={IS_NATIVE}>\n      <HomeHeaderModeProvider>\n        <NotificationsScreenInner />\n      </HomeHeaderModeProvider>\n      <FAB\n        testID=\"composeFAB\"\n        onPress={() => openComposer({logContext: 'Fab'})}\n        icon={<EditBigIcon size=\"lg\" fill={t.palette.white} />}\n        accessibilityRole=\"button\"\n        accessibilityLabel={l({message: 'New post', context: 'action'})}\n        accessibilityHint=\"\"\n      />\n    </Layout.Screen>\n  )\n}","file":"src/screens/Notifications/index.tsx","kind":"component","line":69,"members":{"t":[71,71]},"supers":[]},"PostFeed":{"alsoIn":["src/features/followingV2/home/PostFeed.tsx"],"appearsIn":[["home","h-classes","Logic \u00b7 class diagram"],["home","h-widgets","Screen \u00b7 component composition"],["home","h-sequence","Scroll the Following feed \u00b7 sequence"],["index","h-screens","Screens \u00b7 how the user moves"],["profile","h-classes","Logic \u00b7 class diagram"]],"code":"let PostFeed = ({\n  feed,\n  description,\n  feedParams,\n  ignoreFilterFor,\n  style,\n  enabled,\n  pollInterval,\n  disablePoll,\n  scrollElRef,\n  onScrolledDownChange,\n  onHasNew,\n  renderEmptyState,\n  renderEndOfFeed,\n  testID,\n  headerOffset = 0,\n  progressViewOffset,\n  desktopFixedHeightOffset,\n  ListHeaderComponent,\n  extraData,\n  savedFeedConfig,\n  initialNumToRender: initialNumToRenderOverride,\n  isVideoFeed = false,\n  ref,\n}: {\n  feed: FeedDescriptor\n  description?: RichTextType\n  feedParams?: FeedParams\n  ignoreFilterFor?: string\n  style?: StyleProp<ViewStyle>\n  enabled?: boolean\n  pollInterval?: number\n  disablePoll?: boolean\n  scrollElRef?: ListRef\n  onHasNew?: (v: boolean) => void\n  onScrolledDownChange?: (isScrolledDown: boolean) => void\n  renderEmptyState: () => React.ReactElement\n  renderEndOfFeed?: () => React.ReactElement\n  testID?: string\n  headerOffset?: number\n  progressViewOffset?: number\n  desktopFixedHeightOffset?: number\n  ListHeaderComponent?: () => React.ReactElement\n  extraData?: Record<string, unknown>\n  savedFeedConfig?: app.bsky.actor.defs.SavedFeed\n  initialNumToRender?: number\n  isVideoFeed?: boolean\n  lastFetchDate?: () => number\n  ref?: React.Ref<PostFeedRef>\n}): React.ReactNode => {\n  const ax = useAnalytics()\n  const t = useTheme()\n  const {t: l} = useLingui()\n  const queryClient = useQueryClient()\n  const {currentAccount, hasSession} = useSession()\n  const initialNumToRender = useInitialNumToRender()\n  const feedFeedback = useFeedFeedbackContext()\n  const [isPTRing, setIsPTRing] = useState(false)\n  // eslint-disable-next-line react-hooks/purity\n  const lastFetchRef = useRef<number>(Date.now())\n  const [feedType, feedUriOrActorDid, feedTab] = feed.split('|')\n  const videoGridColumns = useVideoGridColumns()\n  const {rightNavVisible} = useLayoutBreakpoints()\n  const areVideoFeedsEnabled = IS_NATIVE\n\n  const trendingIndices = ax.features.getValue(\n    ax.features.TrendingDiscoverValues,\n    {\n      topics: 5,\n      accounts: 15,\n      videos: 30,\n    },\n  )\n\n  const [hasPressedShowLessUris, setHasPressedShowLessUris] = useState(\n    () => new Set<string>(),\n  )\n  const onPressShowLess = useCallback(\n    (interaction: app.bsky.feed.defs.Interaction) => {\n      if (interaction.item) {\n        const uri = interaction.item\n        setHasPressedShowLessUris(prev => new Set([...prev, uri]))\n        LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut)\n      }\n    },\n    [],\n  )\n\n  const feedCacheKey = feedParams?.feedCacheKey\n  const opts = useMemo(\n    () => ({enabled, ignoreFilterFor}),\n    [enabled, ignoreFilterFor],\n  )\n  const {\n    data,\n    isFetching,\n    isFetched,\n    isError,\n    error,\n    refetch,\n    hasNextPage,\n    isPageFillLimited,\n    isFetchingNextPage,\n    fetchNextPage,\n  } = usePostFeedQuery(feed, feedParams, opts)\n  const lastFetchedAt = data?.pages[0].fetchedAt\n  const isEmpty = useMemo(\n    () => !isFetching && !data?.pages?.some(page => page.slices.length),\n    [isFetching, data],\n  )\n\n  useEffect(() => {\n    if (lastFetchedAt) {\n      lastFetchRef.current = lastFetchedAt\n    }\n  }, [lastFetchedAt])\n\n  const checkForNew = useNonReactiveCallback(async () => {\n    if (!data?.pages[0] || isFetching || !onHasNew || !enabled || disablePoll) {\n      return\n    }\n\n    // Discover always has fresh content\n    if (feedUriOrActorDid === DISCOVER_FEED_URI) {\n      return onHasNew(true)\n    }\n\n    try {\n      if (await pollLatest(data.pages[0])) {\n        if (isEmpty) {\n          void refetch()\n        } else {\n          onHasNew(true)\n        }\n      }\n    } catch (e) {\n      if (!isNetworkError(e)) {\n        logger.warn('Poll latest failed', {feed, message: String(e)})\n      }\n    }\n  })\n\n  const isScrolledDownRef = useRef(false)\n  const handleScrolledDownChange = (isScrolledDown: boolean) => {\n    isScrolledDownRef.current = isScrolledDown\n    onScrolledDownChange?.(isScrolledDown)\n  }\n\n  const myDid = currentAccount?.did || ''\n  const onPostCreated = useCallback(() => {\n    // NOTE\n    // only invalidate if at the top of the feed\n    // changing content when scrolled can trigger some UI freakouts on iOS and android\n    // -sfn\n    if (\n      !isScrolledDownRef.current &&\n      (feed === 'following' ||\n        feed === `author|${myDid}|posts_and_author_threads`)\n    ) {\n      void queryClient.invalidateQueries({queryKey: RQKEY(feed)})\n    }\n  }, [queryClient, feed, myDid])\n  useEffect(() => {\n    return listenPostCreated(onPostCreated)\n  }, [onPostCreated])\n\n  useEffect(() => {\n    if (enabled && !disablePoll) {\n      const timeSinceFirstLoad = Date.now() - lastFetchRef.current\n      if (isEmpty || timeSinceFirstLoad > CHECK_LATEST_AFTER) {\n        // check for new on enable (aka on focus)\n        void checkForNew()\n      }\n    }\n  }, [enabled, isEmpty, disablePoll, checkForNew])\n\n  useEffect(() => {\n    let cleanup1: () => void | undefined, cleanup2: () => void | undefined\n    const subscription = AppState.addEventListener('change', nextAppState => {\n      // check for new on app foreground\n      if (nextAppState === 'active') {\n        void checkForNew()\n      }\n    })\n    cleanup1 = () => subscription.remove()\n    if (pollInterval) {\n      // check for new on interval\n      const i = setInterval(() => {\n        void checkForNew()\n      }, pollInterval)\n      cleanup2 = () => clearInterval(i)\n    }\n    return () => {\n      cleanup1?.()\n      cleanup2?.()\n    }\n  }, [pollInterval, checkForNew])\n\n  const followProgressGuide = useProgressGuide('follow-10')\n  const followAndLikeProgressGuide = useProgressGuide('like-10-and-follow-7')\n\n  const showProgressInterstitial =\n    (followProgressGuide || followAndLikeProgressGuide) && !rightNavVisible\n\n  const {trendingVideoDisabled} = useTrendingSettings()\n\n  const ageAssuranceBannerState = useAgeAssuranceBannerState()\n  const selectedFeed = useSelectedFeed()\n  /**\n   * Cached value of whether the current feed was selected at startup. We don't\n   * want this to update when user swipes.\n   */\n  // oxlint-disable-next-line react/hook-use-state\n  const [isCurrentFeedAtStartupSelected] = useState(selectedFeed === feed)\n\n  const blockedOrMutedAuthors = usePostAuthorShadowFilter(\n    // author feeds have their own handling\n    feed.startsWith('author|') ? undefined : data?.pages,\n  )\n\n  const feedItems: FeedRow[] = useMemo(() => {\n    // wraps a slice item, and replaces it with a showLessFollowup item\n    // if the user has pressed show less on it\n    const sliceItem = (row: Extract<FeedRow, {type: 'sliceItem'}>) => {\n      if (hasPressedShowLessUris.has(row.slice.items[row.indexInSlice]?.uri)) {\n        return {\n          type: 'showLessFollowup',\n          key: row.key,\n        } as const\n      } else {\n        return row\n      }\n    }\n\n    let feedKind: 'following' | 'discover' | 'profile' | 'thevids' | undefined\n    if (feedType === 'following') {\n      feedKind = 'following'\n    } else if (feedUriOrActorDid === DISCOVER_FEED_URI) {\n      feedKind = 'discover'\n    } else if (\n      feedType === 'author' &&\n      (feedTab === 'posts_and_author_threads' ||\n        feedTab === 'posts_with_replies' ||\n        feedTab === 'posts_and_replies_only')\n    ) {\n      feedKind = 'profile'\n    }\n\n    let arr: FeedRow[] = []\n    if (KNOWN_SHUTDOWN_FEEDS.includes(feedUriOrActorDid)) {\n      arr.push({\n        type: 'feedShutdownMsg',\n        key: 'feedShutdownMsg',\n      })\n    }\n    if (isFetched) {\n      if (isError && isEmpty) {\n        arr.push({\n          type: 'error',\n          key: 'error',\n        })\n      } else if (isEmpty) {\n        arr.push({\n          type: 'empty',\n          key: 'empty',\n        })\n      } else if (data) {\n        let sliceIndex = -1\n\n        if (isVideoFeed) {\n          const videos: {\n            item: FeedPostSliceItem\n            feedContext: string | undefined\n            reqId: string | undefined\n          }[] = []\n          for (const page of data.pages) {\n            for (const slice of page.slices) {\n              const item = slice.items.find(\n                item => item.uri === slice.feedPostUri,\n              )\n              if (\n                item &&\n                bsky.isType(app.bsky.embed.video.view, item.post.embed) &&\n                !blockedOrMutedAuthors.includes(item.post.author.did)\n              ) {\n                videos.push({\n                  item,\n                  feedContext: slice.feedContext,\n                  reqId: slice.reqId,\n                })\n              }\n            }\n          }\n\n          const rows: {\n            item: FeedPostSliceItem\n            feedContext: string | undefined\n            reqId: string | undefined\n          }[][] = []\n          for (let i = 0; i < videos.length; i++) {\n            const video = videos[i]\n            const item = video.item\n            const rowItem = {\n              item,\n              feedContext: video.feedContext,\n              reqId: video.reqId,\n            }\n            if (i % videoGridColumns === 0) {\n              rows.push([rowItem])\n            } else {\n              rows[rows.length - 1].push(rowItem)\n            }\n          }\n\n          for (const row of rows) {\n            sliceIndex++\n            arr.push({\n              type: 'videoGridRow',\n              key: row.map(r => r.item._reactKey).join('-'),\n              items: row.map(r => r.item),\n              sourceFeedUri: feedUriOrActorDid,\n              feedContexts: row.map(r => r.feedContext),\n              reqIds: row.map(r => r.reqId),\n            })\n          }\n        } else {\n          for (const page of data?.pages) {\n            for (const slice of page.slices) {\n              sliceIndex++\n\n              if (hasSession) {\n                if (feedKind === 'discover') {\n                  if (sliceIndex === 0) {\n                    if (showProgressInterstitial) {\n                      arr.push({\n                        type: 'interstitialProgressGuide',\n                        key: 'interstitial-' + sliceIndex + '-' + lastFetchedAt,\n                      })\n                    } else {\n                      /*\n                       * Only insert if Discover was the last selected feed at\n                       * startup, the progress guide isn't shown, and the\n                       * banner is eligible to be shown.\n                       */\n                      if (\n                        isCurrentFeedAtStartupSelected &&\n                        ageAssuranceBannerState.visible\n                      ) {\n                        arr.push({\n                          type: 'ageAssuranceBanner',\n                          key: 'ageAssuranceBanner-' + sliceIndex,\n                        })\n                      }\n                    }\n                    arr.push({\n                      type: 'liveEventFeedsAndTrendingBanner',\n                      key: 'liveEventFeedsAndTrendingBanner-' + sliceIndex,\n                    })\n                    // Show composer prompt for Discover and Following feeds\n                    if (\n                      hasSession &&\n                      (feedUriOrActorDid === DISCOVER_FEED_URI ||\n                        feed === 'following')\n                    ) {\n                      arr.push({\n                        type: 'composerPrompt',\n                        key: 'composerPrompt-' + sliceIndex,\n                      })\n                    }\n                  } else if (sliceIndex === trendingIndices.topics) {\n                    arr.push({\n                      type: 'interstitialFeedTrendingTopics',\n                      key: 'interstitialFeedTrendingTopics-' + sliceIndex,\n                      feedSliceIndex: sliceIndex,\n                    })\n                  } else if (sliceIndex === trendingIndices.videos) {\n                    if (areVideoFeedsEnabled && !trendingVideoDisabled) {\n                      arr.push({\n                        type: 'interstitialTrendingVideos',\n                        key: 'interstitial-' + sliceIndex + '-' + lastFetchedAt,\n                      })\n                    }\n                  } else if (sliceIndex === trendingIndices.accounts) {\n                    arr.push({\n                      type: 'interstitialFollows',\n                      key: 'interstitial-' + sliceIndex + '-' + lastFetchedAt,\n                    })\n                  }\n                } else if (feedKind === 'following') {\n                  if (sliceIndex === 0) {\n                    // Show composer prompt for Following feed\n                    if (hasSession) {\n                      arr.push({\n                        type: 'composerPrompt',\n                        key: 'composerPrompt-' + sliceIndex,\n                      })\n                    }\n                  }\n                } else if (feedKind === 'profile') {\n                  if (sliceIndex === 5) {\n                    arr.push({\n                      type: 'interstitialFollows',\n                      key: 'interstitial-' + sliceIndex + '-' + lastFetchedAt,\n                    })\n                  }\n                } else {\n                  /*\n                   * Only insert if this feed was the last selected feed at\n                   * startup and the banner is eligible to be shown.\n                   */\n                  if (sliceIndex === 0 && isCurrentFeedAtStartupSelected) {\n                    arr.push({\n                      type: 'ageAssuranceBanner',\n                      key: 'ageAssuranceBanner-' + sliceIndex,\n                    })\n                  }\n                }\n              }\n\n              if (slice.isFallbackMarker) {\n                arr.push({\n                  type: 'fallbackMarker',\n                  key:\n                    'sliceFallbackMarker-' + sliceIndex + '-' + lastFetchedAt,\n                })\n              } else if (\n                slice.items.some(item =>\n                  blockedOrMutedAuthors.includes(item.post.author.did),\n                )\n              ) {\n                // skip\n              } else if (slice.isIncompleteThread && slice.items.length >= 3) {\n                const beforeLast = slice.items.length - 2\n                const last = slice.items.length - 1\n                arr.push(\n                  sliceItem({\n                    type: 'sliceItem',\n                    key: slice.items[0]._reactKey,\n                    slice: slice,\n                    indexInSlice: 0,\n                    showReplyTo: false,\n                  }),\n                )\n                arr.push({\n                  type: 'sliceViewFullThread',\n                  key: slice._reactKey + '-viewFullThread',\n                  uri: slice.items[0].uri,\n                })\n                arr.push(\n                  sliceItem({\n                    type: 'sliceItem',\n                    key: slice.items[beforeLast]._reactKey,\n                    slice: slice,\n                    indexInSlice: beforeLast,\n                    showReplyTo:\n                      slice.items[beforeLast].parentAuthor?.did !==\n                      slice.items[beforeLast].post.author.did,\n                  }),\n                )\n                arr.push(\n                  sliceItem({\n                    type: 'sliceItem',\n                    key: slice.items[last]._reactKey,\n                    slice: slice,\n                    indexInSlice: last,\n                    showReplyTo: false,\n                  }),\n                )\n              } else {\n                for (let i = 0; i < slice.items.length; i++) {\n                  arr.push(\n                    sliceItem({\n                      type: 'sliceItem',\n                      key: slice.items[i]._reactKey,\n                      slice: slice,\n                      indexInSlice: i,\n                      showReplyTo: i === 0,\n                    }),\n                  )\n                }\n              }\n            }\n          }\n        }\n      }\n      if (isError && !isEmpty) {\n        arr.push({\n          type: 'loadMoreError',\n          key: 'loadMoreError',\n        })\n      }\n    } else {\n      if (isVideoFeed) {\n        arr.push({\n          type: 'videoGridRowPlaceholder',\n          key: 'videoGridRowPlaceholder',\n        })\n      } else {\n        arr.push({\n          type: 'loading',\n          key: 'loading',\n        })\n      }\n    }\n\n    if (description?.text) {\n      arr.unshift({\n        key: 'description',\n        type: 'description',\n        value: description,\n      })\n    }\n\n    return arr\n  }, [\n    description,\n    isFetched,\n    isError,\n    isEmpty,\n    lastFetchedAt,\n    data,\n    feed,\n    feedType,\n    feedUriOrActorDid,\n    feedTab,\n    hasSession,\n    showProgressInterstitial,\n    trendingVideoDisabled,\n    videoGridColumns,\n    isVideoFeed,\n    areVideoFeedsEnabled,\n    hasPressedShowLessUris,\n    ageAssuranceBannerState,\n    isCurrentFeedAtStartupSelected,\n    blockedOrMutedAuthors,\n    trendingIndices,\n  ])\n\n  // events\n  // =\n  //\n\n  const refreshFeed = async () => {\n    if (!enabled) return\n\n    ax.metric('feed:refresh', {\n      feedType: feedType,\n      feedUrl: feed,\n      reason: 'pull-to-refresh',\n    })\n    try {\n      await truncateAndInvalidate(queryClient, RQKEY(feed, feedParams))\n      if (onHasNew) {\n        onHasNew(false)\n      }\n    } catch (err) {\n      logger.error('Failed to refresh posts feed', {message: err})\n    }\n  }\n\n  const onRefresh = async () => {\n    setIsPTRing(true)\n    await refreshFeed()\n    setIsPTRing(false)\n  }\n\n  useImperativeHandle(ref, () => ({\n    refreshFeed,\n  }))\n\n  const onEndReached = useCallback(async () => {\n    if (isFetching || !hasNextPage || isError) return\n\n    ax.metric('feed:endReached', {\n      feedType: feedType,\n      feedUrl: feed,\n      itemCount: feedItems.length,\n    })\n    try {\n      await fetchNextPage()\n    } catch (err) {\n      logger.error('Failed to load more posts', {message: err})\n    }\n  }, [\n    ax,\n    isFetching,\n    hasNextPage,\n    isError,\n    fetchNextPage,\n    feed,\n    feedType,\n    feedItems.length,\n  ])\n\n  const onPressTryAgain = useCallback(() => {\n    void refetch()\n    onHasNew?.(false)\n  }, [refetch, onHasNew])\n\n  const onPressRetryLoadMore = useCallback(() => {\n    void fetchNextPage()\n  }, [fetchNextPage])\n\n  // rendering\n  // =\n\n  const renderItem = useCallback(\n    ({item: row, index: rowIndex}: ListRenderItemInfo<FeedRow>) => {\n      if (row.type === 'empty') {\n        return isPageFillLimited ? <RepliesFeedLimited /> : renderEmptyState()\n      } else if (row.type === 'error') {\n        return (\n          <PostFeedErrorMessage\n            feedDesc={feed}\n            error={error ?? undefined}\n            onPressTryAgain={onPressTryAgain}\n            savedFeedConfig={savedFeedConfig}\n          />\n        )\n      } else if (row.type === 'loadMoreError') {\n        return (\n          <LoadMoreRetryBtn\n            label={l`There was an issue fetching posts. Tap here to try again.`}\n            onPress={onPressRetryLoadMore}\n          />\n        )\n      } else if (row.type === 'loading') {\n        return <PostFeedSkeleton />\n      } else if (row.type === 'feedShutdownMsg') {\n        return <FeedShutdownMsg feedUri={feedUriOrActorDid} />\n      } else if (row.type === 'description') {\n        return (\n          <RichText\n            value={row.value}\n            style={[\n              a.m_md,\n              a.text_md,\n              a.leading_snug,\n              t.atoms.text_contrast_high,\n            ]}\n          />\n        )\n      } else if (row.type === 'interstitialFollows') {\n        return <SuggestedFollows feed={feed} />\n      } else if (row.type === 'interstitialProgressGuide') {\n        return <ProgressGuide />\n      } else if (row.type === 'ageAssuranceBanner') {\n        return <AgeAssuranceDismissibleFeedBanner />\n      } else if (row.type === 'interstitialFeedTrendingTopics') {\n        return (\n          <FeedTrendingTopicsInterstitial feedSliceIndex={row.feedSliceIndex} />\n        )\n      } else if (row.type === 'liveEventFeedsAndTrendingBanner') {\n        return <DiscoverFeedLiveEventFeedsAndTrendingBanner />\n      } else if (row.type === 'composerPrompt') {\n        return <ComposerPrompt />\n      } else if (row.type === 'interstitialTrendingVideos') {\n        return <TrendingVideosInterstitial />\n      } else if (row.type === 'fallbackMarker') {\n        // HACK\n        // tell the user we fell back to discover\n        // see home.ts (feed api) for more info\n        // -prf\n        return <DiscoverFallbackHeader />\n      } else if (row.type === 'sliceItem') {\n        const slice = row.slice\n        const indexInSlice = row.indexInSlice\n        const item = slice.items[indexInSlice]\n        return (\n          <PostFeedItem\n            post={item.post}\n            record={item.record}\n            postNumbering={item.postNumbering}\n            reason={indexInSlice === 0 ? slice.reason : undefined}\n            feedContext={slice.feedContext}\n            reqId={slice.reqId}\n            moderation={item.moderation}\n            parentAuthor={item.parentAuthor}\n            showReplyTo={row.showReplyTo}\n            isThreadParent={isThreadParentAt(slice.items, indexInSlice)}\n            isThreadChild={isThreadChildAt(slice.items, indexInSlice)}\n            isThreadLastChild={\n              isThreadChildAt(slice.items, indexInSlice) &&\n              slice.items.length === indexInSlice + 1\n            }\n            isParentBlocked={item.isParentBlocked}\n            isParentNotFound={item.isParentNotFound}\n            hideTopBorder={rowIndex === 0 && indexInSlice === 0}\n            rootPost={slice.items[0].post}\n            onShowLess={onPressShowLess}\n          />\n        )\n      } else if (row.type === 'sliceViewFullThread') {\n        return <ViewFullThread uri={row.uri} />\n      } else if (row.type === 'videoGridRowPlaceholder') {\n        return (\n          <View>\n            <PostFeedVideoGridRowPlaceholder />\n            <PostFeedVideoGridRowPlaceholder />\n            <PostFeedVideoGridRowPlaceholder />\n          </View>\n        )\n      } else if (row.type === 'videoGridRow') {\n        let sourceContext: VideoFeedSourceContext\n        if (feedType === 'author') {\n          sourceContext = {\n            type: 'author',\n            did: feedUriOrActorDid,\n            filter: feedTab as AuthorFilter,\n          }\n        } else {\n          sourceContext = {\n            type: 'feedgen',\n            uri: row.sourceFeedUri,\n            sourceInterstitial: feedCacheKey ?? 'none',\n          }\n        }\n\n        return (\n          <PostFeedVideoGridRow\n            items={row.items}\n            sourceContext={sourceContext}\n          />\n        )\n      } else if (row.type === 'showLessFollowup') {\n        return <ShowLessFollowup />\n      } else {\n        return null\n      }\n    },\n    [\n      renderEmptyState,\n      isPageFillLimited,\n      feed,\n      error,\n      onPressTryAgain,\n      savedFeedConfig,\n      l,\n      onPressRetryLoadMore,\n      feedType,\n      feedUriOrActorDid,\n      feedTab,\n      feedCacheKey,\n      onPressShowLess,\n      t,\n    ],\n  )\n\n  const shouldRenderPageFillLimit =\n    isPageFillLimited && !isEmpty && !isFetching && !isError\n  const shouldRenderEndOfFeed =\n    !hasNextPage &&\n    !isPageFillLimited &&\n    !isEmpty &&\n    !isFetching &&\n    !isError &&\n    !!renderEndOfFeed\n  const bottomBarOffset = useBottomBarOffset()\n  const FeedFooter = useCallback(() => {\n    /*\n     * A bit of padding at the bottom of the feed as you scroll and when you\n     * reach the end, so that content isn't cut off by the bottom of the\n     * screen. On mobile web, also clear the fixed bottom bar; on native the\n     * doubled headerOffset already covers the tab bar.\n     */\n    const offset =\n      Math.max(headerOffset, 32) * (IS_WEB ? 1 : 2) +\n      (IS_WEB ? bottomBarOffset : 0)\n\n    return isFetchingNextPage ? (\n      <View style={[styles.feedFooter]}>\n        <ActivityIndicator />\n        <View style={{height: offset}} />\n      </View>\n    ) : shouldRenderPageFillLimit ? (\n      <View style={{minHeight: offset}}>\n        <RepliesFeedLimited hasPosts />\n      </View>\n    ) : shouldRenderEndOfFeed ? (\n      <View style={{minHeight: offset}}>{renderEndOfFeed()}</View>\n    ) : (\n      <View style={{height: offset}} />\n    )\n  }, [\n    isFetchingNextPage,\n    shouldRenderPageFillLimit,\n    shouldRenderEndOfFeed,\n    renderEndOfFeed,\n    headerOffset,\n    bottomBarOffset,\n  ])\n\n  const liveNowConfig = useLiveNowConfig()\n\n  const seenActorWithStatusRef = useRef<Set<string>>(new Set())\n  const seenPostUrisRef = useRef<Set<string>>(new Set())\n  // Tracks every post we've seen so we can fire per-post events exactly once,\n  // regardless of the post's position within its slice.\n  const seenPerPostUrisRef = useRef<Set<string>>(new Set())\n\n  // Helper to calculate position in feed (count only root posts, not interstitials or thread replies)\n  const getPostPosition = useNonReactiveCallback(\n    (type: FeedRow['type'], key: string) => {\n      // Calculate position: find the row index in feedItems, then calculate position\n      const rowIndex = feedItems.findIndex(\n        row => row.type === 'sliceItem' && row.key === key,\n      )\n\n      if (rowIndex >= 0) {\n        let position = 0\n        for (let i = 0; i < rowIndex && i < feedItems.length; i++) {\n          const row = feedItems[i]\n          if (row.type === 'sliceItem') {\n            // Only count root posts (indexInSlice === 0), not thread replies\n            if (row.indexInSlice === 0) {\n              position++\n            }\n          } else if (row.type === 'videoGridRow') {\n            // Count each video in the grid row\n            position += row.items.length\n          }\n        }\n        return position\n      }\n    },\n  )\n\n  const onItemSeen = useCallback(\n    (item: FeedRow) => {\n      feedFeedback.onItemSeen(item)\n\n      // Events that should fire exactly once for every new post, regardless of\n      // its position within a slice or video grid row.\n      const onPostSeen = (post: app.bsky.feed.defs.PostView) => {\n        if (seenPerPostUrisRef.current.has(post.uri)) return\n        seenPerPostUrisRef.current.add(post.uri)\n\n        // Standard site embed view tracking\n        if (\n          bsky.isType(app.bsky.embed.external.view, post.embed) &&\n          isStandardSiteEmbed(post.embed.external)\n        ) {\n          ax.metric('embed:standardSite:view', {url: post.embed.external.uri})\n        }\n\n        // Photo embed impression tracking\n        if (\n          bsky.isType(app.bsky.embed.images.view, post.embed) ||\n          bsky.isType(app.bsky.embed.gallery.view, post.embed)\n        ) {\n          const totalImages = bsky.isType(\n            app.bsky.embed.gallery.view,\n            post.embed,\n          )\n            ? post.embed.items.filter(item =>\n                bsky.isType(app.bsky.embed.gallery.viewImage, item),\n              ).length\n            : post.embed.images.length\n          const useExpandedLayout = bsky.isType(\n            app.bsky.embed.gallery.view,\n            post.embed,\n          )\n            ? totalImages > 4\n            : ax.features.enabled(ax.features.PostGalleryEmbedEnable)\n          const layout =\n            totalImages === 1\n              ? 'single'\n              : useExpandedLayout\n                ? 'carousel'\n                : 'grid'\n\n          ax.metric('post:photoEmbed:impression', {\n            layout,\n            totalImages,\n            postUri: post.uri,\n            postAuthorDid: post.author.did,\n            feedDescriptor: feedFeedback.feedDescriptor || feed,\n          })\n        }\n      }\n\n      // Track post:view events\n      if (item.type === 'sliceItem') {\n        const slice = item.slice\n        const indexInSlice = item.indexInSlice\n        const postItem = slice.items[indexInSlice]\n        const post = postItem.post\n\n        onPostSeen(post)\n\n        // Track the post selected by the feed once it is actually visible.\n        if (\n          post.uri === slice.feedPostUri &&\n          !seenPostUrisRef.current.has(post.uri)\n        ) {\n          seenPostUrisRef.current.add(post.uri)\n\n          const position = getPostPosition(\n            'sliceItem',\n            slice.items[0]._reactKey,\n          )\n\n          ax.metric('post:view', {\n            uri: post.uri,\n            authorDid: post.author.did,\n            isReply: !!postItem.record.reply,\n            logContext: 'FeedItem',\n            feedDescriptor: feedFeedback.feedDescriptor || feed,\n            position,\n          })\n        }\n\n        // Live status tracking (existing code)\n        const actor = post.author\n        if (\n          actor.status &&\n          isStatusValidForViewers(actor.status, liveNowConfig) &&\n          isStatusStillActive(actor.status.expiresAt)\n        ) {\n          if (!seenActorWithStatusRef.current.has(actor.did)) {\n            seenActorWithStatusRef.current.add(actor.did)\n            ax.metric('live:view:post', {\n              subject: actor.did,\n              feed,\n            })\n          }\n        }\n      } else if (item.type === 'videoGridRow') {\n        // Track each video in the grid row\n        for (let i = 0; i < item.items.length; i++) {\n          const postItem = item.items[i]\n          const post = postItem.post\n\n          if (!seenPostUrisRef.current.has(post.uri)) {\n            seenPostUrisRef.current.add(post.uri)\n\n            const position = getPostPosition('videoGridRow', item.key)\n\n            ax.metric('post:view', {\n              uri: post.uri,\n              authorDid: post.author.did,\n              isReply: !!postItem.record.reply,\n              logContext: 'FeedItem',\n              feedDescriptor: feedFeedback.feedDescriptor || feed,\n              position,\n            })\n          }\n        }\n      }\n    },\n    [feedFeedback, feed, liveNowConfig, getPostPosition, ax],\n  )\n\n  return (\n    <View testID={testID} style={style}>\n      <List\n        testID={testID ? `${testID}-flatlist` : undefined}\n        ref={scrollElRef}\n        data={feedItems}\n        keyExtractor={(item: FeedRow) => item.key}\n        renderItem={renderItem}\n        ListFooterComponent={FeedFooter}\n        ListHeaderComponent={ListHeaderComponent}\n        refreshing={isPTRing}\n        onRefresh={() => void onRefresh()}\n        headerOffset={headerOffset}\n        progressViewOffset={progressViewOffset}\n        contentContainerStyle={{\n          minHeight: Dimensions.get('window').height * 1.5,\n        }}\n        onScrolledDownChange={handleScrolledDownChange}\n        onEndReached={() => void onEndReached()}\n        onEndReachedThreshold={2} // screen heights from the end, not posts\n        removeClippedSubviews={true}\n        extraData={extraData}\n        desktopFixedHeight={\n          desktopFixedHeightOffset ? desktopFixedHeightOffset : true\n        }\n        initialNumToRender={initialNumToRenderOverride ?? initialNumToRender}\n        windowSize={9}\n        maxToRenderPerBatch={IS_IOS ? 5 : 1}\n        updateCellsBatchingPeriod={40}\n        onItemSeen={onItemSeen}\n      />\n    </View>\n  )\n}","file":"src/view/com/posts/PostFeed.tsx","kind":"component","line":206,"members":{"FeedFooter":[964,996],"ListHeaderComponent":[206,255],"ageAssuranceBannerState":[412,412],"ax":[256,256],"blockedOrMutedAuthors":[421,424],"bottomBarOffset":[963,963],"checkForNew":[323,346],"description":[206,255],"desktopFixedHeightOffset":[206,255],"disablePoll":[206,255],"enabled":[206,255],"extraData":[206,255],"feed":[206,255],"feedFeedback":[262,262],"feedItems":[426,742],"feedParams":[206,255],"feedType":[266,266],"followAndLikeProgressGuide":[405,405],"followProgressGuide":[404,404],"getPostPosition":[1007,1031],"handleScrolledDownChange":[349,352],"hasPressedShowLessUris":[280,282],"headerOffset":[206,255],"ignoreFilterFor":[206,255],"initialNumToRender":[261,261],"initialNumToRenderOverride":[206,255],"isCurrentFeedAtStartupSelected":[419,419],"isEmpty":[312,315],"isPTRing":[263,263],"isScrolledDownRef":[348,348],"isVideoFeed":[206,255],"lastFetchRef":[265,265],"liveNowConfig":[998,998],"onEndReached":[776,798],"onHasNew":[206,255],"onItemSeen":[1033,1157],"onPostCreated":[355,367],"onPressRetryLoadMore":[805,807],"onPressShowLess":[283,292],"onPressTryAgain":[800,803],"onRefresh":[766,770],"onScrolledDownChange":[206,255],"opts":[295,298],"pollInterval":[206,255],"progressViewOffset":[206,255],"queryClient":[259,259],"ref":[206,255],"refreshFeed":[748,764],"renderEmptyState":[206,255],"renderEndOfFeed":[206,255],"renderItem":[812,952],"savedFeedConfig":[206,255],"scrollElRef":[206,255],"seenActorWithStatusRef":[1000,1000],"seenPerPostUrisRef":[1004,1004],"seenPostUrisRef":[1001,1001],"selectedFeed":[413,413],"style":[206,255],"t":[257,257],"testID":[206,255],"videoGridColumns":[267,267]},"supers":[]},"PostThread":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["post-thread","h-classes","Logic \u00b7 class diagram"],["post-thread","h-widgets","Screen \u00b7 component composition"],["post-thread","h-sequence","Open a thread, reply \u00b7 sequence"]],"code":"export function PostThread({uri}: {uri: string}) {\n  const ax = useAnalytics()\n  const showViewCount = ax.features.enabled(ax.features.PostViewCountsEnable)\n  const {gtMobile} = useBreakpoints()\n  const {hasSession} = useSession()\n  const initialNumToRender = useInitialNumToRender()\n  const {height: windowHeight} = useWindowDimensions()\n  const anchorPostSource = usePostSource(uri)\n  /*\n   * Only the anchor is the feed item the user tapped, so only it reports feed\n   * feedback. Parents and replies get the feed for analytics but no item.\n   */\n  const anchorFeedItem = useMemo(\n    () =>\n      anchorPostSource ? feedItemFromPostSource(anchorPostSource) : undefined,\n    [anchorPostSource],\n  )\n  const feedFeedback = useFeedFeedback(\n    anchorPostSource?.feedSourceInfo,\n    hasSession,\n    'thread',\n  )\n\n  /*\n   * One query to rule them all\n   */\n  const thread = usePostThread({anchor: uri})\n  const {anchor, hasParents} = useMemo(() => {\n    let hasParents = false\n    for (const item of thread.data.items) {\n      if (item.type === 'threadPost' && item.depth === 0) {\n        return {anchor: item, hasParents}\n      }\n      hasParents = true\n    }\n    return {hasParents}\n  }, [thread.data.items])\n\n  useSetPostTitle(anchor?.value.post.author)\n\n  // Track post:view event when anchor post is viewed\n  const seenPostUriRef = useRef<string | null>(null)\n  useEffect(() => {\n    if (\n      anchor?.type === 'threadPost' &&\n      anchor.value.post.uri !== seenPostUriRef.current\n    ) {\n      const post = anchor.value.post\n      seenPostUriRef.current = post.uri\n\n      ax.metric('post:view', {\n        uri: post.uri,\n        authorDid: post.author.did,\n        isReply: !!post.record.reply,\n        logContext: 'Post',\n        feedDescriptor: feedFeedback.feedDescriptor,\n      })\n    }\n  }, [ax, anchor, feedFeedback.feedDescriptor])\n\n  // Track post:view events for parent posts and replies (non-anchor posts)\n  const trackThreadItemView = usePostViewTracking('PostThreadItem')\n\n  const {openComposer} = useOpenComposer()\n  const optimisticOnPostReply = useNonReactiveCallback(\n    (payload: OnPostSuccessData) => {\n      if (payload) {\n        const {replyToUri, posts} = payload\n        if (replyToUri && posts.length) {\n          thread.actions.insertReplies(replyToUri, posts)\n        }\n      }\n    },\n  )\n  const onReplyToAnchor = useNonReactiveCallback(() => {\n    if (anchor?.type !== 'threadPost') {\n      return\n    }\n    const post = anchor.value.post\n    openComposer({\n      replyTo: {\n        uri: anchor.uri,\n        cid: post.cid,\n        text: post.record.text,\n        author: post.author,\n        embed: post.embed,\n        moderation: anchor.moderation,\n        langs: post.record.langs,\n      },\n      onPostSuccess: optimisticOnPostReply,\n      logContext: 'PostReply',\n    })\n\n    if (anchorFeedItem) {\n      feedFeedback.sendInteraction({\n        item: anchorFeedItem.uri,\n        event: 'app.bsky.feed.defs#interactionReply',\n        feedContext: anchorFeedItem.feedContext,\n        reqId: anchorFeedItem.reqId,\n      })\n    }\n  })\n\n  const isRoot = !!anchor && anchor.value.post.record.reply === undefined\n  const canReply = !anchor?.value.post?.viewer?.replyDisabled\n  const [maxParentCount, setMaxParentCount] = useState(PARENT_CHUNK_SIZE)\n  const [maxChildrenCount, setMaxChildrenCount] = useState(CHILDREN_CHUNK_SIZE)\n  const totalParentCount = useRef(0) // recomputed below\n  const totalChildrenCount = useRef(thread.data.items.length) // recomputed below\n  const listRef = useRef<ListMethods>(null)\n  const anchorRef = useRef<React.ComponentRef<typeof View> | null>(null)\n  const headerRef = useRef<React.ComponentRef<typeof View> | null>(null)\n\n  /*\n   * On a cold load, parents are not prepended until the anchor post has\n   * rendered as the first item in the list. This gives us a consistent\n   * reference point for which to pin the anchor post to the top of the screen.\n   *\n   * We simulate a cold load any time the user changes the view or sort params\n   * so that this handling is consistent.\n   *\n   * On native, `maintainVisibleContentPosition={{minIndexForVisible: 0}}` gives\n   * us this for free, since the anchor post is the first item in the list.\n   *\n   * On web, `onContentSizeChange` is used to get ahead of next paint and handle\n   * this scrolling.\n   */\n  const [deferParents, setDeferParents] = useState(true)\n  /**\n   * Used to flag whether we should scroll to the anchor post. On a cold load,\n   * this is always true. And when a user changes thread parameters, we also\n   * manually set this to true.\n   */\n  const shouldHandleScroll = useRef(true)\n  /**\n   * Called any time the content size of the list changes. Could be a fresh\n   * render, items being added to the list, or any resize that changes the\n   * scrollable size of the content.\n   *\n   * We want this to fire every time we change params (which will reset\n   * `deferParents` via `onLayout` on the anchor post, due to the key change),\n   * or click into a new post (which will result in a fresh `deferParents`\n   * hook).\n   *\n   * The result being: any intentional change in view by the user will result\n   * in the anchor being pinned as the first item.\n   */\n  const onContentSizeChangeWebOnly = web(() => {\n    const list = listRef.current\n    const anchor = anchorRef.current as any as Element\n    const header = headerRef.current as any as Element\n\n    if (list && anchor && header && shouldHandleScroll.current) {\n      const anchorOffsetTop = anchor.getBoundingClientRect().top\n      const headerHeight = header.getBoundingClientRect().height\n\n      /*\n       * `deferParents` is `true` on a cold load, and always reset to\n       * `true` when params change via `prepareForParamsUpdate`.\n       *\n       * On a cold load or a push to a new post, on the first pass of this\n       * logic, the anchor post is the first item in the list. Therefore\n       * `anchorOffsetTop - headerHeight` will be 0.\n       *\n       * When a user changes thread params, on the first pass of this logic,\n       * the anchor post may not move (if there are no parents above it), or it\n       * may have gone off the screen above, because of the sudden lack of\n       * parents due to `deferParents === true`. This negative value (minus\n       * `headerHeight`) will result in a _negative_ `offset` value, which will\n       * scroll the anchor post _down_ to the top of the screen.\n       *\n       * However, `prepareForParamsUpdate` also resets scroll to `0`, so when a user\n       * changes params, the anchor post's offset will actually be equivalent\n       * to the `headerHeight` because of how the DOM is stacked on web.\n       * Therefore, `anchorOffsetTop - headerHeight` will once again be 0,\n       * which means the first pass in this case will result in no scroll.\n       *\n       * Then, once parents are prepended, this will fire again. Now, the\n       * `anchorOffsetTop` will be positive, which minus the header height,\n       * will give us a _positive_ offset, which will scroll the anchor post\n       * back _up_ to the top of the screen.\n       */\n      const offset = anchorOffsetTop - headerHeight\n      list.scrollToOffset({offset})\n\n      /*\n       * After we manage to do a positive adjustment, we need to ensure this\n       * doesn't run again until scroll handling is requested again via\n       * `shouldHandleScroll.current === true` and a params change via\n       * `prepareForParamsUpdate`.\n       *\n       * The `isRoot` here is needed because if we're looking at the anchor\n       * post, this handler will not fire after `deferParents` is set to\n       * `false`, since there are no parents to render above it. In this case,\n       * we want to make sure `shouldHandleScroll` is set to `false` right away\n       * so that subsequent size changes unrelated to a params change (like\n       * pagination) do not affect scroll.\n       */\n      if (offset > 0 || isRoot) shouldHandleScroll.current = false\n    }\n  })\n\n  /**\n   * Ditto the above, but for native.\n   */\n  const onContentSizeChangeNativeOnly = native(() => {\n    const list = listRef.current\n    const anchor = anchorRef.current\n\n    if (list && anchor && shouldHandleScroll.current) {\n      /*\n       * `prepareForParamsUpdate` is called any time the user changes thread params like\n       * `view` or `sort`, which sets `deferParents(true)` and resets the\n       * scroll to the top of the list. However, there is a split second\n       * where the top of the list is wherever the parents _just were_. So if\n       * there were parents, the anchor is not at the top of the list just\n       * prior to this handler being called.\n       *\n       * Once this handler is called, the anchor post is the first item in\n       * the list (because of `deferParents` being `true`), and so we can\n       * synchronously scroll the list back to the top of the list (which is\n       * 0 on native, no need to handle `headerHeight`).\n       */\n      list.scrollToOffset({\n        animated: false,\n        offset: 0,\n      })\n\n      /*\n       * After this first pass, `deferParents` will be `false`, and those\n       * will render in. However, the anchor post will retain its position\n       * because of `maintainVisibleContentPosition` handling on native. So we\n       * don't need to let this handler run again, like we do on web.\n       */\n      shouldHandleScroll.current = false\n    }\n  })\n\n  /**\n   * Called any time the user changes thread params, such as `view` or `sort`.\n   * Prepares the UI for repositioning of the scroll so that the anchor post is\n   * always at the top after a params change.\n   *\n   * No need to handle max parents here, deferParents will handle that and we\n   * want it to re-render with the same items above the anchor.\n   */\n  const prepareForParamsUpdate = useCallback(() => {\n    /**\n     * Truncate list so that anchor post is the first item in the list. Manual\n     * scroll handling on web is predicated on this, and on native, this allows\n     * `maintainVisibleContentPosition` to do its thing.\n     */\n    setDeferParents(true)\n    // reset this to a lower value for faster re-render\n    setMaxChildrenCount(CHILDREN_CHUNK_SIZE)\n    // set flag\n    shouldHandleScroll.current = true\n  }, [setDeferParents, setMaxChildrenCount])\n\n  const setSortWrapped = useCallback(\n    (sort: string) => {\n      prepareForParamsUpdate()\n      thread.actions.setSort(sort)\n    },\n    [thread, prepareForParamsUpdate],\n  )\n\n  const setViewWrapped = useCallback(\n    (view: ThreadViewOption) => {\n      prepareForParamsUpdate()\n      thread.actions.setView(view)\n    },\n    [thread, prepareForParamsUpdate],\n  )\n\n  const onStartReached = () => {\n    if (thread.state.isFetching) return\n    // can be true after `prepareForParamsUpdate` is called\n    if (deferParents) return\n    // prevent any state mutations if we know we're done\n    if (maxParentCount >= totalParentCount.current) return\n    setMaxParentCount(n => n + PARENT_CHUNK_SIZE)\n  }\n\n  const onEndReached = () => {\n    if (thread.state.isFetching) return\n    // can be true after `prepareForParamsUpdate` is called\n    if (deferParents) return\n    // prevent any state mutations if we know we're done\n    if (maxChildrenCount >= totalChildrenCount.current) return\n    setMaxChildrenCount(prev => prev + CHILDREN_CHUNK_SIZE)\n  }\n\n  const slices = useMemo(() => {\n    const results: ThreadItem[] = []\n\n    if (!thread.data.items.length) return results\n\n    /*\n     * Pagination hack, tracks the # of items below the anchor post.\n     */\n    let childrenCount = 0\n\n    for (let i = 0; i < thread.data.items.length; i++) {\n      const item = thread.data.items[i]\n      /*\n       * Need to check `depth`, since not found or blocked posts are not\n       * `threadPost`s, but still have `depth`.\n       */\n      const hasDepth = 'depth' in item\n\n      /*\n       * Handle anchor post.\n       */\n      if (hasDepth && item.depth === 0) {\n        results.push(item)\n\n        // Recalculate total parents current index.\n        totalParentCount.current = i\n        // Recalculate total children using (length - 1) - current index.\n        totalChildrenCount.current = thread.data.items.length - 1 - i\n\n        /*\n         * Walk up the parents, limiting by `maxParentCount`\n         */\n        if (!deferParents) {\n          const start = i - 1\n          if (start >= 0) {\n            const limit = Math.max(0, start - maxParentCount)\n            for (let pi = start; pi >= limit; pi--) {\n              results.unshift(thread.data.items[pi])\n            }\n          }\n        }\n      } else {\n        // ignore any parent items\n        if (item.type === 'readMoreUp' || (hasDepth && item.depth < 0)) continue\n        // can exit early if we've reached the max children count\n        if (childrenCount > maxChildrenCount) break\n\n        results.push(item)\n        childrenCount++\n      }\n    }\n\n    return results\n  }, [thread, deferParents, maxParentCount, maxChildrenCount])\n\n  /**\n   * Defer rendering reply skeletons so that the anchor post (from cache)\n   * can paint without being blocked by skeleton layout work. On mount,\n   * skeletons are filtered out. After the first render, they're added\n   * back via a low-priority transition.\n   */\n  const [showReplySkeletons, setShowReplySkeletons] = useState(false)\n  useEffect(() => {\n    if (thread.state.isPlaceholderData && !showReplySkeletons) {\n      startTransition(() => {\n        setShowReplySkeletons(true)\n      })\n    }\n  }, [thread.state.isPlaceholderData, showReplySkeletons])\n\n  const deferredSlices = useMemo(() => {\n    if (showReplySkeletons) return slices\n    return slices.filter(\n      item => !(item.type === 'skeleton' && item.item === 'reply'),\n    )\n  }, [slices, showReplySkeletons])\n\n  const isTombstoneView = useMemo(() => {\n    if (deferredSlices.length > 1) return false\n    return deferredSlices.every(\n      s => s.type === 'threadPostBlocked' || s.type === 'threadPostNotFound',\n    )\n  }, [deferredSlices])\n\n  const renderItem = useCallback(\n    ({item, index}: {item: ThreadItem; index: number}) => {\n      if (item.type === 'threadPost') {\n        if (item.depth < 0) {\n          return (\n            <ThreadItemPost\n              item={item}\n              threadgateRecord={thread.data.threadgate?.record ?? undefined}\n              overrides={{\n                topBorder: index === 0,\n              }}\n              onPostSuccess={optimisticOnPostReply}\n            />\n          )\n        } else if (item.depth === 0) {\n          return (\n            /*\n             * Keep this view wrapped so that the anchor post is always index 0\n             * in the list and `maintainVisibleContentPosition` can do its\n             * thing.\n             */\n            <View collapsable={false}>\n              <View\n                /*\n                 * IMPORTANT: this is a load-bearing key on all platforms. We\n                 * want to force `onLayout` to fire any time the thread params\n                 * change so that `deferParents` is always reset to `false` once\n                 * the anchor post is rendered.\n                 *\n                 * If we ever add additional thread params to this screen, they\n                 * will need to be added here.\n                 */\n                key={item.uri + thread.state.view + thread.state.sort}\n                ref={anchorRef}\n                onLayout={() => setDeferParents(false)}\n              />\n              <FeedItemProvider value={anchorFeedItem}>\n                <ThreadItemAnchor\n                  item={item}\n                  showViewCount={showViewCount}\n                  threadgateRecord={thread.data.threadgate?.record ?? undefined}\n                  onPostSuccess={optimisticOnPostReply}\n                />\n              </FeedItemProvider>\n            </View>\n          )\n        } else {\n          if (thread.state.view === 'tree') {\n            return (\n              <ThreadItemTreePost\n                item={item}\n                threadgateRecord={thread.data.threadgate?.record ?? undefined}\n                overrides={{\n                  moderation: thread.state.otherItemsVisible && item.depth > 0,\n                }}\n                onPostSuccess={optimisticOnPostReply}\n              />\n            )\n          } else {\n            return (\n              <ThreadItemPost\n                item={item}\n                threadgateRecord={thread.data.threadgate?.record ?? undefined}\n                overrides={{\n                  moderation: thread.state.otherItemsVisible && item.depth > 0,\n                }}\n                onPostSuccess={optimisticOnPostReply}\n              />\n            )\n          }\n        }\n      } else if (item.type === 'threadPostNoUnauthenticated') {\n        if (item.depth < 0) {\n          return <ThreadItemPostNoUnauthenticated item={item} />\n        } else if (item.depth === 0) {\n          return <ThreadItemAnchorNoUnauthenticated />\n        }\n      } else if (item.type === 'readMore') {\n        return (\n          <ThreadItemReadMore\n            item={item}\n            view={thread.state.view === 'tree' ? 'tree' : 'linear'}\n          />\n        )\n      } else if (item.type === 'readMoreUp') {\n        return <ThreadItemReadMoreUp item={item} />\n      } else if (item.type === 'threadPostBlocked') {\n        return <ThreadItemPostTombstone type=\"blocked\" />\n      } else if (item.type === 'threadPostNotFound') {\n        return <ThreadItemPostTombstone type=\"not-found\" />\n      } else if (item.type === 'replyComposer') {\n        return (\n          <View>\n            {gtMobile && (\n              <ThreadComposePrompt onPressCompose={onReplyToAnchor} />\n            )}\n          </View>\n        )\n      } else if (item.type === 'showOtherReplies') {\n        return <ThreadItemShowOtherReplies onPress={item.onPress} />\n      } else if (item.type === 'skeleton') {\n        if (item.item === 'anchor') {\n          return <ThreadItemAnchorSkeleton />\n        } else if (item.item === 'reply') {\n          if (thread.state.view === 'linear') {\n            return <ThreadItemPostSkeleton index={index} />\n          } else {\n            return <ThreadItemTreePostSkeleton index={index} />\n          }\n        } else if (item.item === 'replyComposer') {\n          return <ThreadItemReplyComposerSkeleton />\n        }\n      }\n      return null\n    },\n    [\n      thread,\n      optimisticOnPostReply,\n      onReplyToAnchor,\n      gtMobile,\n      anchorFeedItem,\n      showViewCount,\n    ],\n  )\n\n  const defaultListFooterHeight = hasParents ? windowHeight - 200 : undefined\n\n  return (\n    <PostThreadContextProvider context={thread.context}>\n      <Layout.Header.Outer headerRef={headerRef}>\n        <Layout.Header.BackButton />\n        <Layout.Header.Content>\n          <Layout.Header.TitleText>\n            <Trans context=\"description\">Post</Trans>\n          </Layout.Header.TitleText>\n        </Layout.Header.Content>\n        <Layout.Header.Slot>\n          <HeaderDropdown\n            sort={thread.state.sort}\n            setSort={setSortWrapped}\n            view={thread.state.view}\n            setView={setViewWrapped}\n          />\n        </Layout.Header.Slot>\n      </Layout.Header.Outer>\n\n      {thread.state.error ? (\n        <ThreadError\n          error={thread.state.error}\n          onRetry={thread.actions.refetch}\n        />\n      ) : (\n        <FeedFeedbackProvider value={feedFeedback}>\n          <List\n            ref={listRef}\n            data={deferredSlices}\n            renderItem={renderItem}\n            keyExtractor={keyExtractor}\n            onContentSizeChange={platform({\n              web: onContentSizeChangeWebOnly,\n              default: onContentSizeChangeNativeOnly,\n            })}\n            onStartReached={onStartReached}\n            onEndReached={onEndReached}\n            onEndReachedThreshold={4}\n            onStartReachedThreshold={1}\n            onItemSeen={item => {\n              // Track post:view for parent posts and replies (non-anchor posts)\n              if (item.type === 'threadPost' && item.depth !== 0) {\n                trackThreadItemView(item.value.post)\n              }\n            }}\n            /**\n             * NATIVE ONLY\n             * {@link https://reactnative.dev/docs/scrollview#maintainvisiblecontentposition}\n             */\n            maintainVisibleContentPosition={{minIndexForVisible: 0}}\n            /*\n             * The web anchor positioning in onContentSizeChangeWebOnly reads\n             * the parents' layout as they're prepended, so the thread renders\n             * every row on web.\n             */\n            disableVirtualization={IS_WEB}\n            desktopFixedHeight\n            sideBorders={false}\n            ListFooterComponent={\n              <ListFooter\n                /*\n                 * On native, if `deferParents` is true, we need some extra buffer to\n                 * account for the `on*ReachedThreshold` values.\n                 *\n                 * Otherwise, and on web, this value needs to be the height of\n                 * the viewport _minus_ a sensible min-post height e.g. 200, so\n                 * that there's enough scroll remaining to get the anchor post\n                 * back to the top of the screen when handling scroll.\n                 */\n                height={platform({\n                  web: defaultListFooterHeight,\n                  default: deferParents\n                    ? windowHeight * 2\n                    : defaultListFooterHeight,\n                })}\n                style={isTombstoneView ? {borderTopWidth: 0} : undefined}\n              />\n            }\n            initialNumToRender={initialNumToRender}\n            /**\n             * Default: 21\n             *\n             * Smaller for placeholder data so we don't waste time rendering skeletons\n             */\n            windowSize={thread.state.isPlaceholderData ? 1 : 7}\n            /**\n             * Default: 10\n             */\n            maxToRenderPerBatch={5}\n            /**\n             * Default: 50\n             */\n            updateCellsBatchingPeriod={100}\n          />\n        </FeedFeedbackProvider>\n      )}\n\n      {!gtMobile && canReply && hasSession && (\n        <MobileComposePrompt onPressReply={onReplyToAnchor} />\n      )}\n    </PostThreadContextProvider>\n  )\n}","file":"src/screens/PostThread/index.tsx","kind":"component","line":68,"members":{"anchorFeedItem":[80,84],"anchorPostSource":[75,75],"anchorRef":[178,178],"ax":[69,69],"deferParents":[195,195],"deferredSlices":[431,436],"feedFeedback":[85,89],"headerRef":[179,179],"initialNumToRender":[73,73],"isTombstoneView":[438,443],"listRef":[177,177],"maxChildrenCount":[174,174],"maxParentCount":[173,173],"onContentSizeChangeNativeOnly":[273,304],"onContentSizeChangeWebOnly":[215,268],"onEndReached":[352,359],"onReplyToAnchor":[142,169],"onStartReached":[343,350],"optimisticOnPostReply":[132,141],"prepareForParamsUpdate":[314,325],"renderItem":[445,568],"seenPostUriRef":[109,109],"setSortWrapped":[327,333],"setViewWrapped":[335,341],"shouldHandleScroll":[201,201],"showReplySkeletons":[422,422],"slices":[361,414],"thread":[94,94],"totalChildrenCount":[176,176],"totalParentCount":[175,175],"trackThreadItemView":[129,129],"uri":[68,68]},"supers":[]},"ProfileScreenInner":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["profile","h-classes","Logic \u00b7 class diagram"],["profile","h-sequence","Open a profile \u00b7 sequence"]],"code":"function ProfileScreenInner({route}: Props) {\n  const {_} = useLingui()\n  const {currentAccount} = useSession()\n  const queryClient = useQueryClient()\n  const name =\n    route.params.name === 'me' ? currentAccount?.did : route.params.name\n  const moderationOpts = useModerationOpts()\n  const {\n    data: resolvedDid,\n    error: resolveError,\n    refetch: refetchDid,\n    isPending: isDidPending,\n  } = useResolveDidQuery(name)\n  const {\n    data: profile,\n    error: profileError,\n    refetch: refetchProfile,\n    isPlaceholderData: isPlaceholderProfile,\n    isPending: isProfilePending,\n  } = useProfileQuery({\n    did: resolvedDid,\n  })\n\n  const onPressTryAgain = useCallback(() => {\n    if (resolveError) {\n      void refetchDid()\n    } else {\n      void refetchProfile()\n    }\n  }, [resolveError, refetchDid, refetchProfile])\n\n  // Apply hard-coded redirects as need\n  useEffect(() => {\n    if (resolveError) {\n      if (name === 'lulaoficial.bsky.social') {\n        console.log('Applying redirect to lula.com.br')\n        void navigate({name: 'Profile', params: {name: 'lula.com.br'}})\n      }\n    }\n  }, [name, resolveError])\n\n  // When we open the profile, we want to reset the posts query if we are blocked.\n  useEffect(() => {\n    if (resolvedDid && profile?.viewer?.blockedBy) {\n      resetProfilePostsQueries(queryClient, resolvedDid)\n    }\n  }, [queryClient, profile?.viewer?.blockedBy, resolvedDid])\n\n  // Most pushes will happen here, since we will have only placeholder data\n  // A disabled dependent query remains pending, so only consider the profile\n  // pending once handle resolution has produced a DID.\n  if (isDidPending || (!!resolvedDid && isProfilePending)) {\n    return (\n      <Layout.Content>\n        <ProfileHeaderLoading />\n      </Layout.Content>\n    )\n  }\n  if (resolveError || profileError) {\n    return (\n      <SafeAreaView style={[a.flex_1]}>\n        <ErrorScreen\n          testID=\"profileErrorScreen\"\n          title={profileError ? _(msg`Not Found`) : _(msg`Oops!`)}\n          message={cleanError(resolveError || profileError)}\n          onPressTryAgain={onPressTryAgain}\n          showHeader\n        />\n      </SafeAreaView>\n    )\n  }\n  if (profile && moderationOpts) {\n    return (\n      <ProfileScreenLoaded\n        key={\n          route.params.tab !== undefined\n            ? `${profile.did}-${route.params.tab}-${isPlaceholderProfile}`\n            : profile.did\n        }\n        profile={profile}\n        moderationOpts={moderationOpts}\n        isPlaceholderProfile={isPlaceholderProfile}\n        hideBackButton={!!route.params.hideBackButton}\n        tab={route.params.tab}\n      />\n    )\n  }\n  // should never happen\n  return (\n    <SafeAreaView style={[a.flex_1]}>\n      <ErrorScreen\n        testID=\"profileErrorScreen\"\n        title=\"Oops!\"\n        message=\"Something went wrong and we're not sure what.\"\n        onPressTryAgain={onPressTryAgain}\n        showHeader\n      />\n    </SafeAreaView>\n  )\n}","file":"src/view/screens/Profile.tsx","kind":"component","line":91,"members":{"moderationOpts":[97,97],"onPressTryAgain":[114,120],"queryClient":[94,94],"route":[91,91]},"supers":[]},"SearchScreenShell":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["search","h-classes","Logic \u00b7 class diagram"],["search","h-widgets","Screen \u00b7 component composition"],["search","h-sequence","Search for a topic \u00b7 sequence"]],"code":"export function SearchScreenShell({\n  queryParam,\n  testID,\n  fixedParams,\n  navButton = 'menu',\n  inputPlaceholder,\n  isExplore,\n}: {\n  queryParam: string\n  testID: string\n  fixedParams?: SearchFilters\n  navButton?: 'back' | 'menu'\n  inputPlaceholder?: string\n  isExplore?: boolean\n}) {\n  const ax = useAnalytics()\n  const t = useTheme()\n  const {gtMobile} = useBreakpoints()\n  const navigation =\n    useNavigation<\n      NavigationProp<CommonNavigatorParams, 'Search' | 'ProfileSearch'>\n    >()\n  const route = useRoute()\n  const textInput = useRef<React.ComponentRef<typeof TextInput>>(null)\n  const {t: l} = useLingui()\n  const {currentAccount} = useSession()\n  const queryClient = useQueryClient()\n  const isFocused = useIsFocused()\n\n  useViewportZoomLock({enabled: isFocused})\n\n  // Get tab parameter from route params\n  const tabParam = (route.params as {q?: string; tab?: TabParam})?.tab\n  const [activeTab, setActiveTab] = useState(() => getTabIndex(tabParam))\n\n  /*\n   * A raw `from:me` operator stays visible in the search input. Submitting the\n   * advanced dialog promotes it to a structured `from=me` filter and removes\n   * it from `q`; the API layer reconstructs the operator for post search.\n   */\n  const {query, fromMe, filters, setFilters, hasFilters} = useQueryManager({\n    initialQuery: queryParam,\n    fixedParams,\n  })\n\n  // Query terms\n  const [searchText, setSearchText] = useState<string>(query)\n  const searchTextRef = useRef(searchText)\n  const updateSearchText = useCallback((text: string) => {\n    searchTextRef.current = text\n    setSearchText(text)\n  }, [])\n\n  const {items: autocompleteItems, isFetching: isAutocompleteFetching} =\n    useAutocomplete({\n      type: 'profile',\n      /*\n       * On web the dropdown (SearchAutocompleteInput) owns its own autocomplete\n       * query; only the native inline list consumes this one, so pass an empty\n       * query on web to keep the hook a no-op instead of doing wasted work.\n       */\n      query: IS_NATIVE ? searchText : '',\n    })\n\n  const [showAutocomplete, setShowAutocomplete] = useState(false)\n\n  const [termHistory = [], setTermHistory] = useStorage(account, [\n    currentAccount?.did ?? 'pwi',\n    'searchTermHistory',\n  ] as const)\n  const [accountHistory = [], setAccountHistory] = useStorage(account, [\n    currentAccount?.did ?? 'pwi',\n    'searchAccountHistory',\n  ])\n\n  const {data: accountHistoryProfiles} = useProfilesQuery({\n    handles: accountHistory,\n    maintainData: true,\n  })\n\n  const updateSearchHistory = useCallback(\n    (q: string, searchFilters: SearchFilters = {}) => {\n      if (!q) return\n      /*\n       * Store the query plus any advanced-search filters. Term-only searches\n       * serialize to a plain string (back-compatible with existing history);\n       * filtered searches serialize to JSON. Dedupe on the serialized form.\n       */\n      const item = serializeHistoryEntry(q, searchFilters)\n      const newSearchHistory = [\n        item,\n        ...termHistory.filter(search => search !== item),\n      ].slice(0, 6)\n      setTermHistory(newSearchHistory)\n    },\n    [termHistory, setTermHistory],\n  )\n\n  const updateProfileHistory = useCallback(\n    (item: bsky.profile.AnyProfileView) => {\n      const newAccountHistory = [\n        item.did,\n        ...accountHistory.filter(p => p !== item.did),\n      ].slice(0, 10)\n      setAccountHistory(newAccountHistory)\n    },\n    [accountHistory, setAccountHistory],\n  )\n\n  const deleteSearchHistoryItem = useCallback(\n    (item: string) => {\n      setTermHistory(termHistory.filter(search => search !== item))\n    },\n    [termHistory, setTermHistory],\n  )\n  const deleteProfileHistoryItem = useCallback(\n    (item: bsky.profile.AnyProfileView) => {\n      setAccountHistory(accountHistory.filter(p => p !== item.did))\n    },\n    [accountHistory, setAccountHistory],\n  )\n  const clearAllHistory = useCallback(() => {\n    ax.metric('search:recent:clearAll', {\n      termCount: termHistory.length,\n      profileCount: accountHistory.length,\n    })\n    setTermHistory([])\n    setAccountHistory([])\n  }, [ax, termHistory, accountHistory, setTermHistory, setAccountHistory])\n\n  const showFilters = Boolean((query || hasFilters) && !showAutocomplete)\n\n  const onChangeLang = useCallback(\n    (lang: string) => {\n      setFilters({...filters, lang: lang || undefined})\n    },\n    [filters, setFilters],\n  )\n\n  // web only - measure header height for sticky positioning\n  const [headerHeight, setHeaderHeight] = useState(0)\n  const headerRef = useRef(null)\n  useLayoutEffect(() => {\n    if (IS_WEB) {\n      if (!headerRef.current) return\n      const measurement = (headerRef.current as Element).getBoundingClientRect()\n      setHeaderHeight(measurement.height)\n    }\n  }, [])\n\n  /*\n   * On native, navigating to an already-mounted Search screen with a new `q`\n   * (e.g. from a post hashtag/search link) updates the route param without\n   * remounting, so re-sync the input. Web handles this via the focus effect\n   * below, which fires on back/forward navigation.\n   */\n  useEffect(() => {\n    if (IS_NATIVE) {\n      // eslint-disable-next-line react-hooks/set-state-in-effect\n      updateSearchText(query)\n    }\n  }, [query, updateSearchText])\n  useFocusEffect(\n    useNonReactiveCallback(() => {\n      if (IS_WEB) {\n        updateSearchText(query)\n      }\n    }),\n  )\n\n  const onPressClearQuery = useCallback(() => {\n    scrollToTopWeb()\n    /*\n     * Clearing the query also resets any advanced-search filters, then keeps\n     * the input focused so the user can immediately type a new search.\n     */\n    if (IS_WEB) {\n      /*\n       * Replace the param set so q/tab/filters drop out of the URL instead of\n       * serializing as the literal string \"undefined\". fixedParams live on the\n       * route already and are preserved by withoutSearchParams.\n       */\n      const parameters = withoutSearchParams(\n        route.params as Record<string, unknown>,\n      )\n      // @ts-expect-error route is not typesafe\n      navigation.replace(route.name, parameters)\n    } else {\n      updateSearchText('')\n      navigation.setParams({...filtersToRouteParams({}), q: ''})\n    }\n    textInput.current?.focus()\n  }, [updateSearchText, navigation, route])\n\n  const onChangeText = useCallback(\n    (text: string) => {\n      scrollToTopWeb()\n      updateSearchText(text)\n    },\n    [updateSearchText],\n  )\n\n  const navigateToItem = useCallback(\n    (item: string, itemFilters: SearchFilters = filters) => {\n      scrollToTopWeb()\n      setShowAutocomplete(false)\n      updateSearchHistory(item, itemFilters)\n\n      if (IS_WEB) {\n        const nextParams = {\n          ...withoutFilterParams(route.params as Record<string, unknown>),\n          ...definedFilterParams(itemFilters),\n          q: item,\n        }\n        // @ts-expect-error route is not typesafe\n        navigation.push(route.name, nextParams)\n      } else {\n        textInput.current?.blur()\n        navigation.setParams({...filtersToRouteParams(itemFilters), q: item})\n      }\n    },\n    [updateSearchHistory, navigation, route, filters],\n  )\n\n  const onPressCancelSearch = useCallback(() => {\n    scrollToTopWeb()\n    textInput.current?.blur()\n    setShowAutocomplete(false)\n    if (IS_WEB) {\n      /*\n       * Empty params resets the URL to be /search rather than /search?q=\n       * Also clear tab and advanced-search filter parameters.\n       */\n      const parameters = withoutSearchParams(\n        route.params as Record<string, unknown>,\n      )\n      // @ts-expect-error route is not typesafe\n      navigation.replace(route.name, parameters)\n    } else {\n      updateSearchText('')\n      navigation.setParams({\n        ...filtersToRouteParams({}),\n        q: '',\n        tab: undefined,\n      })\n    }\n  }, [\n    setShowAutocomplete,\n    updateSearchText,\n    navigation,\n    route.params,\n    route.name,\n  ])\n\n  const onSubmit = (source: 'typed' | 'autocomplete') => () => {\n    const nextQuery = searchTextRef.current\n    ax.metric('search:query', {\n      source,\n      filterCount: countActiveFilters(filters),\n    })\n    navigateToItem(nextQuery)\n  }\n\n  const onSubmitAdvanced = useCallback(\n    (text: string, nextFilters: SearchFilters) => {\n      scrollToTopWeb()\n      setShowAutocomplete(false)\n      updateSearchText(text)\n      updateSearchHistory(text, nextFilters)\n      ax.metric('search:query', {\n        source: 'typed',\n        filterCount: countActiveFilters(nextFilters),\n      })\n      if (IS_WEB) {\n        /*\n         * Build a fresh param set so removed filters drop out of the URL.\n         * Only defined filters are included - undefined values would serialize\n         * as the literal string \"undefined\".\n         */\n        const nextParams = {\n          ...withoutFilterParams(route.params as Record<string, unknown>),\n          ...definedFilterParams(nextFilters),\n          q: text,\n        }\n        // @ts-expect-error route is not typesafe\n        navigation.push(route.name, nextParams)\n      } else {\n        textInput.current?.blur()\n        // setParams merges, so pass undefined for absent keys to clear them.\n        navigation.setParams({...filtersToRouteParams(nextFilters), q: text})\n      }\n    },\n    [ax, navigation, route, updateSearchText, updateSearchHistory],\n  )\n\n  const onAutocompleteResultPress = useCallback(() => {\n    if (IS_WEB) {\n      setShowAutocomplete(false)\n    } else {\n      textInput.current?.blur()\n    }\n  }, [])\n\n  const handleHistoryItemClick = useCallback(\n    (item: string) => {\n      /*\n       * History entries may carry advanced-search filters (JSON-encoded);\n       * term-only entries are plain strings. Restore both the query and\n       * filters.\n       */\n      const {q, filters: itemFilters} = parseHistoryEntry(item)\n      updateSearchText(q)\n      navigateToItem(q, itemFilters)\n    },\n    [navigateToItem, updateSearchText],\n  )\n\n  const handleProfileClick = useCallback(\n    (profile: bsky.profile.AnyProfileView) => {\n      updateSearchText('')\n      unstableCacheProfileView(queryClient, profile)\n      // Slight delay to avoid updating during push nav animation.\n      setTimeout(() => {\n        updateProfileHistory(profile)\n      }, 400)\n    },\n    [updateProfileHistory, queryClient, updateSearchText],\n  )\n\n  /**\n   * Web only. Selecting a profile from the anchored autocomplete dropdown.\n   */\n  const onSelectProfile = useCallback(\n    (profile: bsky.profile.AnyProfileView, position: number) => {\n      ax.metric('search:autocomplete:press', {\n        profileDid: profile.did,\n        position,\n      })\n      handleProfileClick(profile)\n      navigation.navigate('Profile', {name: profile.handle})\n    },\n    [ax, handleProfileClick, navigation],\n  )\n\n  /**\n   * Web only. Selecting the \"Search for X\" row from the anchored autocomplete\n   * dropdown. This runs the typed query as-is (not a suggested profile), so it\n   * is attributed to `typed` rather than `autocomplete`.\n   */\n  const onSelectSearch = useCallback(\n    (value: string) => {\n      ax.metric('search:query', {\n        source: 'typed',\n        filterCount: countActiveFilters(filters),\n      })\n      updateSearchText(value)\n      navigateToItem(value)\n    },\n    [ax, filters, navigateToItem, updateSearchText],\n  )\n\n  const onSoftReset = useCallback(() => {\n    if (IS_WEB) {\n      /*\n       * Empty params resets the URL to be /search rather than /search?q=\n       * Also clear tab and advanced-search filter parameters.\n       */\n      const parameters = withoutSearchParams(\n        route.params as Record<string, unknown>,\n      )\n      // @ts-expect-error route is not typesafe\n      navigation.replace(route.name, parameters)\n    } else {\n      updateSearchText('')\n      navigation.setParams({\n        ...filtersToRouteParams({}),\n        q: '',\n        tab: undefined,\n      })\n      textInput.current?.focus()\n    }\n  }, [navigation, route.name, route.params, updateSearchText])\n\n  useFocusEffect(\n    useCallback(() => {\n      return listenSoftReset(onSoftReset)\n    }, [onSoftReset]),\n  )\n\n  const onSearchInputFocus = useCallback(() => {\n    if (IS_WEB) {\n      // Prevent a jump on iPad by ensuring that\n      // the initial focused render has no result list.\n      requestAnimationFrame(() => {\n        setShowAutocomplete(true)\n      })\n    } else {\n      setShowAutocomplete(true)\n    }\n  }, [setShowAutocomplete])\n\n  const focusSearchInput = useCallback(\n    (tab?: TabParam) => {\n      textInput.current?.focus()\n\n      // If a tab is specified, set the tab parameter\n      if (tab) {\n        if (IS_WEB) {\n          navigation.setParams({...route.params, tab})\n        } else {\n          navigation.setParams({tab})\n        }\n      }\n    },\n    [navigation, route],\n  )\n\n  const onShareSearch = useCallback(() => {\n    const url = new URL('https://bsky.app')\n    url.pathname = '/search'\n    if (query) url.searchParams.set('q', query)\n    for (const [key, value] of Object.entries(definedFilterParams(filters))) {\n      url.searchParams.set(key, value)\n    }\n    ax.metric('search:shareLink:press', {\n      filterCount: countActiveFilters(filters),\n    })\n    setStringAsync(url.toString()).then(\n      () => Toast.show(l`Copied link to clipboard`, {type: 'success'}),\n      () => Toast.show(l`Failed to copy link`, {type: 'error'}),\n    )\n  }, [ax, query, filters, l])\n\n  const showHeader = !gtMobile || navButton !== 'menu'\n\n  return (\n    <Layout.Screen testID={testID}>\n      <View\n        ref={headerRef}\n        onLayout={evt => {\n          if (IS_WEB) setHeaderHeight(evt.nativeEvent.layout.height)\n        }}\n        style={[\n          a.relative,\n          a.z_10,\n          web({\n            position: 'sticky',\n            top: 0,\n          }),\n        ]}>\n        <Layout.Center style={t.atoms.bg}>\n          {showHeader && (\n            <View\n              // HACK: shift up search input. we can't remove the top padding\n              // on the search input because it messes up the layout animation\n              // if we add it only when the header is hidden\n              style={{marginBottom: tokens.space.xs * -1}}>\n              <Layout.Header.Outer noBottomBorder>\n                {navButton === 'menu' ? (\n                  <Layout.Header.MenuButton />\n                ) : (\n                  <Layout.Header.BackButton />\n                )}\n                <Layout.Header.Content align=\"left\">\n                  <Layout.Header.TitleText>\n                    {isExplore ? <Trans>Explore</Trans> : <Trans>Search</Trans>}\n                  </Layout.Header.TitleText>\n                </Layout.Header.Content>\n                {showFilters ? (\n                  <View style={[a.flex_row, a.align_center, a.gap_sm]}>\n                    <AdvancedSearchDialog\n                      disabled={activeTab > 1}\n                      q={searchText}\n                      filters={filters}\n                      onSubmit={onSubmitAdvanced}\n                    />\n                    <Button\n                      accessibilityRole=\"button\"\n                      size=\"small\"\n                      color=\"secondary\"\n                      shape=\"round\"\n                      label={l`Share this search`}\n                      onPress={onShareSearch}>\n                      <ButtonIcon icon={ShareIcon} />\n                    </Button>\n                  </View>\n                ) : (\n                  <Layout.Header.Slot />\n                )}\n              </Layout.Header.Outer>\n            </View>\n          )}\n          <View style={[a.px_lg, a.pt_sm, a.pb_sm, a.overflow_hidden]}>\n            <View style={[a.gap_sm]}>\n              {!!query && !showAutocomplete && (\n                <DetectedLanguagesAdmonition\n                  query={query}\n                  filters={filters}\n                  sort={activeTab === 1 ? 'latest' : 'top'}\n                  enabled={activeTab === 0 || activeTab === 1}\n                  onPressLanguage={onChangeLang}\n                />\n              )}\n\n              <View style={[a.w_full, a.flex_row, a.align_stretch, a.gap_sm]}>\n                <View style={[a.flex_1, a.flex_row, a.align_center, a.gap_sm]}>\n                  {showAutocomplete && (\n                    <Button\n                      label={l`Cancel search`}\n                      size=\"small\"\n                      variant=\"ghost\"\n                      color=\"secondary\"\n                      shape=\"round\"\n                      style={[a.px_sm]}\n                      onPress={onPressCancelSearch}\n                      hitSlop={HITSLOP_10}>\n                      <ButtonIcon icon={ArrowLeftIcon} size=\"lg\" />\n                    </Button>\n                  )}\n                  <View style={[a.flex_1]}>\n                    <SearchAutocompleteInput\n                      testID=\"searchScreenInput\"\n                      ref={textInput}\n                      value={searchText}\n                      onFocus={onSearchInputFocus}\n                      onChangeText={onChangeText}\n                      onClearText={onPressClearQuery}\n                      onSubmitEditing={onSubmit('typed')}\n                      placeholder={inputPlaceholder ?? l`Search`}\n                      hitSlop={{...HITSLOP_20, top: 0}}\n                      hotkey={true}\n                      fixedParams={Boolean(fixedParams)}\n                      onSelectProfile={onSelectProfile}\n                      onSelectSearch={onSelectSearch}\n                    />\n                  </View>\n                </View>\n                {showFilters && !showHeader ? (\n                  <View style={[a.flex_row, a.align_center, a.gap_sm]}>\n                    <AdvancedSearchDialog\n                      disabled={activeTab > 1}\n                      q={searchText}\n                      filters={filters}\n                      onSubmit={onSubmitAdvanced}\n                    />\n                    <Button\n                      accessibilityRole=\"button\"\n                      size=\"small\"\n                      color=\"secondary\"\n                      shape=\"round\"\n                      label={l`Share this search`}\n                      onPress={onShareSearch}>\n                      <ButtonIcon icon={ShareIcon} />\n                    </Button>\n                  </View>\n                ) : null}\n              </View>\n            </View>\n          </View>\n        </Layout.Center>\n      </View>\n\n      <View style={[a.flex_1, a.relative]}>\n        <View style={[a.flex_1, web(showAutocomplete && a.hidden)]}>\n          <SearchScreenInner\n            key={filters.lang ?? ''}\n            activeTab={activeTab}\n            setActiveTab={setActiveTab}\n            query={query}\n            filters={filters}\n            hasFilters={hasFilters}\n            fromMe={fromMe}\n            headerHeight={headerHeight}\n            focusSearchInput={focusSearchInput}\n          />\n        </View>\n\n        {showAutocomplete && !fixedParams && (\n          <Animated.View\n            entering={native(FadeInDown.easing(Easing.out(Easing.cubic)))}\n            exiting={native(FadeOutDown.easing(Easing.out(Easing.cubic)))}\n            style={platform({\n              web: [a.flex_1],\n              native: [t.atoms.bg, a.absolute, a.inset_0],\n            })}\n            accessibilityViewIsModal\n            accessibilityRole=\"list\">\n            {searchText.length > 0 && IS_NATIVE ? (\n              <AutocompleteResults\n                items={autocompleteItems}\n                isFetching={isAutocompleteFetching}\n                searchText={searchText}\n                onSubmit={onSubmit('autocomplete')}\n                onResultPress={onAutocompleteResultPress}\n                onProfileClick={handleProfileClick}\n              />\n            ) : (\n              <SearchHistory\n                searchHistory={termHistory}\n                selectedProfiles={\n                  accountHistoryProfiles?.profiles.filter(p =>\n                    accountHistory.includes(p.did),\n                  ) ?? []\n                }\n                onItemClick={handleHistoryItemClick}\n                onProfileClick={handleProfileClick}\n                onRemoveItemClick={deleteSearchHistoryItem}\n                onRemoveProfileClick={deleteProfileHistoryItem}\n                onClearAll={clearAllHistory}\n              />\n            )}\n          </Animated.View>\n        )}\n      </View>\n    </Layout.Screen>\n  )\n}","file":"src/screens/Search/Shell.tsx","kind":"component","line":108,"members":{"accountHistory":[178,181],"activeTab":[141,141],"ax":[123,123],"clearAllHistory":[229,236],"deleteProfileHistoryItem":[223,228],"deleteSearchHistoryItem":[217,222],"fixedParams":[108,122],"focusSearchInput":[509,523],"handleHistoryItemClick":[411,423],"handleProfileClick":[425,435],"headerHeight":[248,248],"headerRef":[249,249],"inputPlaceholder":[108,122],"isExplore":[108,122],"isFocused":[135,135],"navButton":[108,122],"navigateToItem":[310,330],"navigation":[126,129],"onAutocompleteResultPress":[403,409],"onChangeLang":[240,245],"onChangeText":[302,308],"onPressCancelSearch":[332,360],"onPressClearQuery":[278,300],"onSearchInputFocus":[497,507],"onSelectProfile":[440,450],"onSelectSearch":[457,467],"onShareSearch":[525,539],"onSoftReset":[469,489],"onSubmit":[362,369],"onSubmitAdvanced":[371,401],"queryClient":[134,134],"queryParam":[108,122],"route":[130,130],"searchText":[154,154],"searchTextRef":[155,155],"showAutocomplete":[172,172],"t":[124,124],"termHistory":[174,177],"testID":[108,122],"textInput":[131,131],"updateProfileHistory":[206,215],"updateSearchHistory":[188,204],"updateSearchText":[156,159]},"supers":[]},"StepInfo":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["sign-up","h-classes","Logic \u00b7 class diagram"],["sign-up","h-widgets","Screen \u00b7 component composition"],["sign-up","h-sequence","Create an account \u00b7 sequence"]],"code":"export function StepInfo({\n  onPressBack,\n  isServerError,\n  refetchServer,\n  isLoadingStarterPack,\n}: {\n  onPressBack: () => void\n  isServerError: boolean\n  refetchServer: () => void\n  isLoadingStarterPack: boolean\n}) {\n  const {t: l} = useLingui()\n  const ax = useAnalytics()\n  const {state, dispatch} = useSignupContext()\n  const preemptivelyCompleteActivePolicyUpdate =\n    usePreemptivelyCompleteActivePolicyUpdate()\n\n  /**\n   * The last email we ran the \"did you really mean this?\" check against, so\n   * the warning is only shown once per distinct address.\n   */\n  const prevEmailValueRef = useRef<string>(state.email)\n\n  const emailInputRef = useRef<React.ComponentRef<typeof TextInput>>(null)\n  const passwordInputRef = useRef<React.ComponentRef<typeof TextInput>>(null)\n  const birthdateInputRef = useRef<DateFieldRef>(null)\n\n  const aaRegionConfig = useAgeAssuranceRegionConfigWithFallback()\n  const {setDeviceGeolocation} = useDeviceGeolocationApi()\n  const locationControl = Dialog.useDialogControl()\n  const isOverRegionMinAccessAge = state.dateOfBirth\n    ? !isUnderAge(state.dateOfBirth.toISOString(), aaRegionConfig.minAccessAge)\n    : true\n  const isOverAppMinAccessAge = state.dateOfBirth\n    ? !isUnderAge(state.dateOfBirth.toISOString(), MIN_ACCESS_AGE)\n    : true\n  const isOverMinAdultAge = state.dateOfBirth\n    ? !isUnderAge(state.dateOfBirth.toISOString(), 18)\n    : true\n  const isDeviceGeolocationGranted = useIsDeviceGeolocationGranted()\n\n  const [hasWarnedEmail, setHasWarnedEmail] = useState<boolean>(false)\n\n  const tldtsRef = useRef<typeof tldts>(undefined)\n  useEffect(() => {\n    void loadTLDs().then(tldts => {\n      tldtsRef.current = tldts\n    })\n    // This will get used in the avatar creator a few steps later, so lets preload it now\n    void preloadViewShot()\n  }, [])\n\n  const onNextPress = () => {\n    const {inviteCode, email, password} = state\n    const emailChanged = prevEmailValueRef.current !== email\n\n    if (!isOverRegionMinAccessAge) {\n      return\n    }\n\n    if (state.serviceDescription?.inviteCodeRequired && !inviteCode) {\n      return dispatch({\n        type: 'setError',\n        value: l`Please enter your invite code.`,\n        field: 'invite-code',\n      })\n    }\n    if (!email) {\n      return dispatch({\n        type: 'setError',\n        value: l`Please enter your email.`,\n        field: 'email',\n      })\n    }\n    if (!EmailValidator.validate(email)) {\n      return dispatch({\n        type: 'setError',\n        value: l`Your email appears to be invalid.`,\n        field: 'email',\n      })\n    }\n    if (emailChanged && tldtsRef.current) {\n      if (isEmailMaybeInvalid(email, tldtsRef.current)) {\n        prevEmailValueRef.current = email\n        setHasWarnedEmail(true)\n        return dispatch({\n          type: 'setError',\n          value: l`Please double-check that you have entered your email address correctly.`,\n        })\n      }\n    } else if (hasWarnedEmail) {\n      setHasWarnedEmail(false)\n    }\n    prevEmailValueRef.current = email\n    if (!password) {\n      return dispatch({\n        type: 'setError',\n        value: l`Please choose your password.`,\n        field: 'password',\n      })\n    }\n    if (password.length < 8) {\n      return dispatch({\n        type: 'setError',\n        value: l`Your password must be at least 8 characters long.`,\n        field: 'password',\n      })\n    }\n    if (!state.dateOfBirth) {\n      return dispatch({\n        type: 'setError',\n        value: l`Please enter your date of birth.`,\n        field: 'date-of-birth',\n      })\n    }\n\n    preemptivelyCompleteActivePolicyUpdate()\n    dispatch({type: 'next'})\n    ax.metric('signup:nextPressed', {\n      activeStep: state.activeStep,\n    })\n  }\n\n  return (\n    <>\n      <View style={[a.gap_md, a.pt_lg]}>\n        {!!state.error && (\n          <Admonition.Admonition type=\"error\">\n            {state.error}\n          </Admonition.Admonition>\n        )}\n        <HostingProvider\n          minimal\n          serviceUrl={state.serviceUrl}\n          onSelectServiceUrl={v => dispatch({type: 'setServiceUrl', value: v})}\n        />\n        {state.isLoading || isLoadingStarterPack ? (\n          <View style={[a.align_center]}>\n            <Loader size=\"xl\" />\n          </View>\n        ) : state.serviceDescription ? (\n          <>\n            {state.serviceDescription.inviteCodeRequired && (\n              <View>\n                <TextField.LabelText>\n                  <Trans>Invite code</Trans>\n                </TextField.LabelText>\n                <TextField.Root isInvalid={state.errorField === 'invite-code'}>\n                  <TextField.Icon icon={Ticket} />\n                  <TextField.Input\n                    onChangeText={value => {\n                      dispatch({type: 'setInviteCode', value: value.trim()})\n                      if (\n                        state.errorField === 'invite-code' &&\n                        value.trim().length > 0\n                      ) {\n                        dispatch({type: 'clearError'})\n                      }\n                    }}\n                    label={l`Required for this provider`}\n                    value={state.inviteCode}\n                    autoCapitalize=\"none\"\n                    autoComplete=\"email\"\n                    keyboardType=\"email-address\"\n                    returnKeyType=\"next\"\n                    submitBehavior={native('submit')}\n                    onSubmitEditing={native(() =>\n                      emailInputRef.current?.focus(),\n                    )}\n                  />\n                </TextField.Root>\n              </View>\n            )}\n            <View>\n              <TextField.LabelText>\n                <Trans>Email</Trans>\n              </TextField.LabelText>\n              <TextField.Root isInvalid={state.errorField === 'email'}>\n                <TextField.Icon icon={Envelope} />\n                <TextField.Input\n                  testID=\"emailInput\"\n                  inputRef={emailInputRef}\n                  onChangeText={value => {\n                    dispatch({type: 'setEmail', value: value.trim()})\n                    if (hasWarnedEmail) {\n                      setHasWarnedEmail(false)\n                    }\n                    if (\n                      state.errorField === 'email' &&\n                      value.trim().length > 0 &&\n                      EmailValidator.validate(value.trim())\n                    ) {\n                      dispatch({type: 'clearError'})\n                    }\n                  }}\n                  label={l`Enter your email address`}\n                  value={state.email}\n                  autoCapitalize=\"none\"\n                  autoComplete=\"email\"\n                  keyboardType=\"email-address\"\n                  returnKeyType=\"next\"\n                  submitBehavior={native('submit')}\n                  onSubmitEditing={native(() =>\n                    passwordInputRef.current?.focus(),\n                  )}\n                />\n              </TextField.Root>\n            </View>\n            <View>\n              <TextField.LabelText>\n                <Trans>Password</Trans>\n              </TextField.LabelText>\n              <PasswordField\n                isInvalid={state.errorField === 'password'}\n                testID=\"passwordInput\"\n                inputRef={passwordInputRef}\n                onChangeText={value => {\n                  dispatch({type: 'setPassword', value})\n                  if (state.errorField === 'password' && value.length >= 8) {\n                    dispatch({type: 'clearError'})\n                  }\n                }}\n                label={l`Choose your password`}\n                value={state.password}\n                autoComplete=\"new-password\"\n                returnKeyType=\"next\"\n                submitBehavior={native('blurAndSubmit')}\n                onSubmitEditing={native(() =>\n                  birthdateInputRef.current?.focus(),\n                )}\n                passwordRules=\"minlength: 8;\"\n              />\n            </View>\n            <View>\n              <DateField.LabelText>\n                <Trans>Your birth date</Trans>\n              </DateField.LabelText>\n              <DateField.DateField\n                testID=\"date\"\n                inputRef={birthdateInputRef}\n                value={state.dateOfBirth ?? ''}\n                isInvalid={state.errorField === 'date-of-birth'}\n                onChangeDate={date => {\n                  dispatch({\n                    type: 'setDateOfBirth',\n                    value: sanitizeDate(new Date(date)),\n                  })\n                  if (state.errorField === 'date-of-birth') {\n                    dispatch({type: 'clearError'})\n                  }\n                }}\n                label={l`Date of birth`}\n                placeholder={l`Select your date of birth`}\n                accessibilityHint={l`Select your date of birth`}\n                maximumDate={new Date()}\n              />\n            </View>\n\n            <View style={[a.gap_sm]}>\n              <Policies serviceDescription={state.serviceDescription} />\n\n              {!isOverRegionMinAccessAge || !isOverAppMinAccessAge ? (\n                <Admonition.Outer type=\"error\">\n                  <Admonition.Row>\n                    <Admonition.Icon />\n                    <Admonition.Content>\n                      <Admonition.Text>\n                        <Plural\n                          value={aaRegionConfig.minAccessAge}\n                          other=\"You must be # years of age or older to create an account in your region.\"\n                        />\n                      </Admonition.Text>\n                      {IS_NATIVE &&\n                        !isDeviceGeolocationGranted &&\n                        isOverAppMinAccessAge && (\n                          <Admonition.Text>\n                            <Trans>\n                              Have we got your location wrong?{' '}\n                              <SimpleInlineLinkText\n                                label={l`Tap here to update your location with GPS.`}\n                                {...createStaticClick(() => {\n                                  locationControl.open()\n                                })}>\n                                Tap here to update your location with GPS.\n                              </SimpleInlineLinkText>\n                            </Trans>\n                          </Admonition.Text>\n                        )}\n                    </Admonition.Content>\n                  </Admonition.Row>\n                </Admonition.Outer>\n              ) : !isOverMinAdultAge ? (\n                <Admonition.Admonition type=\"warning\">\n                  <Trans>\n                    If you are not yet an adult according to the laws of your\n                    country, your parent or legal guardian must read these Terms\n                    on your behalf.\n                  </Trans>\n                </Admonition.Admonition>\n              ) : undefined}\n            </View>\n\n            {IS_NATIVE && (\n              <DeviceLocationRequestDialog\n                control={locationControl}\n                onLocationAcquired={props => {\n                  props.closeDialog(() => {\n                    // set this after close!\n                    setDeviceGeolocation(props.geolocation)\n                    Toast.show(l`Your location has been updated.`, {\n                      type: 'success',\n                    })\n                  })\n                }}\n              />\n            )}\n          </>\n        ) : undefined}\n      </View>\n      <BackNextButtons\n        hideNext={!isOverRegionMinAccessAge}\n        showRetry={isServerError}\n        isLoading={state.isLoading}\n        onBackPress={onPressBack}\n        onNextPress={onNextPress}\n        onRetryPress={refetchServer}\n        overrideNextText={hasWarnedEmail ? l`It's correct` : undefined}\n      />\n    </>\n  )\n}","file":"src/screens/Signup/StepInfo/index.tsx","kind":"component","line":62,"members":{"aaRegionConfig":[89,89],"ax":[74,74],"birthdateInputRef":[87,87],"emailInputRef":[85,85],"hasWarnedEmail":[103,103],"isDeviceGeolocationGranted":[101,101],"isLoadingStarterPack":[62,72],"isServerError":[62,72],"locationControl":[91,91],"onNextPress":[114,183],"onPressBack":[62,72],"passwordInputRef":[86,86],"preemptivelyCompleteActivePolicyUpdate":[76,77],"prevEmailValueRef":[83,83],"refetchServer":[62,72],"tldtsRef":[105,105]},"shot":"shots/code/StepInfo.jpg","supers":[]}},"sourceUrl":"https://github.com/bluesky-social/social-app/blob/f7399a645c08dcf5d15f8cac64417ac73fe6ddf9/"};
